c_runtime/c_args.das:
options gen2

module c_args public

require crt
require daslib/clargs

//! C's `main(argc, argv)`: `c_runtime_init(name)` builds the argument vector once, in C-allocator
//! memory, from the program's own arguments (`get_user_args`: after `--` under the interpreter
//! and the JIT, after the binary in a `-exe` one), `name` the C program's name in `argv[0]`;
//! `c_argc` and `c_argv` hand it to the converted `c_main`. Every string and the vector are the
//! C program's to keep and write, so none lives on the das heap.

var private argv_vector : uint8 ??
var private argc_count = 0

// a NUL-terminated copy of `s` in C-allocator memory
def private c_string(s : string) : uint8? {
    let n = length(s)
    unsafe {
        var bytes = reinterpret<uint8?>(crt::malloc(uint64(n) + 1ul))
        if (n > 0) {
            crt::memcpy(reinterpret<void?>(bytes), reinterpret<void?>(s), uint64(n))
        }
        deref(bytes + n) = uint8(0)
        return bytes
    }
}

//! The vector `argv`: `name`, then each argument the program was given, then the null C puts at
//! `argv[argc]`; a second call keeps the first vector.
def c_runtime_init(name : string) {
    if (argv_vector != null) {
        return
    }
    let args <- get_user_args()
    argc_count = length(args) + 1
    unsafe {
        argv_vector = reinterpret<uint8 ??>(crt::malloc(uint64(argc_count + 1) * 8ul))
        deref(argv_vector) = c_string(name)
        for (idx, arg in range(1, argc_count), args) {
            deref(argv_vector + idx) = c_string(arg)
        }
        deref(argv_vector + argc_count) = null
    }
}

//! `argc`: the count `c_runtime_init` found, the name included.
def c_argc : int => argc_count

//! `argv`: the vector `c_runtime_init` built.
def c_argv : uint8 ?? => argv_vector

c_runtime/c_bitfields.das:
options gen2

module c_bitfields public

require daslib/cmp
require strings
require daslib/ast
require daslib/ast_boost
require daslib/templates_boost
require daslib/macro_boost
require c_runtime/c_storage

//! C bitfields over das storage. `[c_bitfields(a = 3, b = 5)] struct BF { a : uint; b : int; e : int16 }`
//! is written C-shaped; the annotation replaces each allocation unit's fields with one unsigned
//! storage field `_bits<N>` at the unit's place and generates, per bitfield, the property pair
//! `operator . a` / `operator . a :=` doing the mask and shift. The argument list is read in order:
//! `_bits<N> = "uint8"` (or `"uint16"`, `"uint"`, `"uint64"`, or `"uint8[k]"`, `k` bytes at
//! alignment 1) opens a unit, `_<K> = n` skips `n` bits of padding, any other `name = width`
//! places the field `name` at the unit's bit cursor. A bitfield with no unit open opens `_bits<K>`
//! sized by the field's own type. The property pairs are `c_storage`'s arithmetic, in `uint` or
//! `uint64`, since das defines no shift on the 8- and 16-bit storage types.

// a bitfield of a unit: its field's index in the struct and its place in the unit
struct private BitMember {
    fidx : int
    access : BitAccess
}

// a unit: its storage type, and for a byte unit (`"uint8[k]"`) its `count` of bytes, else 0
struct private BitUnit {
    name : string
    storage : string
    bits : int
    count : int
    cursor : int
    members : array<BitMember>
}

// the storage a bitfield of type `t` opens by default: the unsigned type of its width; an empty
// name for a type that cannot hold a bitfield
def private default_storage(t : TypeDeclPtr) : CStorage => t.isInteger || t.isBool ? storage_of("", t.sizeOf * 8) : CStorage()

def private all_digits(s : string; from : int) : bool {
    var digits = length(s) > from
    peek_data(s) $(bytes) {
        for (idx in range(from, length(bytes))) {
            digits = digits && is_number(int(bytes[idx]))
        }
    }
    return digits
}

// the `k` of a byte unit's storage `"uint8[k]"`, 1 to 8; 0 for any other spelling
def private byte_unit_count(spelled : string) : int {
    if (!(spelled |> starts_with("uint8[")) || !(spelled |> ends_with("]"))) {
        return 0
    }
    let digits = slice(spelled, 6, length(spelled) - 1)
    if (!all_digits(digits, 0)) {
        return 0
    }
    let count = to_int(digits)
    return count <= 8 ? count : 0
}

def private is_opener(name : string) : bool => name |> starts_with("_bits") && all_digits(name, 5)

def private is_padding(name : string) : bool => name |> starts_with("_") && all_digits(name, 1)

// opens unit `name` of `storage`, which must not be a field of the struct or another unit
def private open_unit(st : StructurePtr; var units : array<BitUnit>; name : string; storage : CStorage; count : int; var errors : das_string) : bool {
    if (field_index(st, name) >= 0) {
        errors := "c_bitfields: unit `{name}` collides with a field of {st.name}"
        return false
    }
    for (u in units) {
        if (u.name == name) {
            errors := "c_bitfields: unit `{name}` is opened twice"
            return false
        }
    }
    units |> emplace(BitUnit(name = name, storage = storage.name, bits = count == 0 ? storage.bits : 8 * count, count = count))
    return true
}

// advances the open unit's cursor past `bits` bits of padding
def private skip_padding(var units : array<BitUnit>; name : string; bits : int; var errors : das_string) : bool {
    if (empty(units)) {
        errors := "c_bitfields: padding `{name}` before any unit"
        return false
    }
    if (bits < 0) {
        errors := "c_bitfields: padding `{name}` of {bits} bits is negative"
        return false
    }
    assume pad_unit = units[length(units) - 1]
    pad_unit.cursor += bits
    if (pad_unit.cursor > pad_unit.bits) {
        errors := "c_bitfields: padding `{name}` runs past unit `{pad_unit.name}`"
        return false
    }
    return true
}

// the units the argument list describes, in order; false with `errors` set on any argument the
// grammar or the struct refuses
def private read_units(st : StructurePtr; args : AnnotationArgumentList; var units : array<BitUnit>; var errors : das_string) : bool {
    var named : table<string>
    for (a in args) {
        let name = string(a.name)
        if (is_opener(name)) {
            let spelled = a.basicType == Type.tString ? string(a.sValue) : "?"
            let count = byte_unit_count(spelled)
            let storage = count > 0 ? storage_of("uint8", 0) : storage_of(spelled, 0)
            if (empty(storage.name)) {
                errors := "c_bitfields: unit `{name}` names storage `{a.sValue}`; expecting \"uint8\", \"uint16\", \"uint\", \"uint64\" or \"uint8[k]\", k from 1 to 8"
                return false
            }
            if (!open_unit(st, units, name, storage, count, errors)) {
                return false
            }
            continue
        }
        if (a.basicType != Type.tInt) {
            errors := "c_bitfields: argument `{name}` is not a width"
            return false
        }
        if (is_padding(name)) {
            if (!skip_padding(units, name, a.iValue, errors)) {
                return false
            }
            continue
        }
        let fidx = field_index(st, name)
        if (fidx < 0) {
            errors := "c_bitfields: {st.name} has no field `{name}`"
            return false
        }
        if (key_exists(named, name)) {
            errors := "c_bitfields: field `{name}` is named twice"
            return false
        }
        named |> insert(name)
        let ftype = st.fields[fidx]._type
        let default_unit = default_storage(ftype)
        if (empty(default_unit.name)) {
            errors := "c_bitfields: field `{name}` of type {describe(ftype)} is not a bitfield type"
            return false
        }
        if (st.fields[fidx].init != null) {
            errors := "c_bitfields: field `{name}` has an initializer; a bitfield starts at zero"
            return false
        }
        if (empty(units) && !open_unit(st, units, "_bits0", default_unit, 0, errors)) {
            return false
        }
        assume unit = units[length(units) - 1]
        let width = a.iValue
        if (ftype.isBool && width != 1) {
            errors := "c_bitfields: bool field `{name}` is 1 bit wide, not {width}"
            return false
        }
        if (width < 1 || unit.cursor + width > unit.bits) {
            errors := "c_bitfields: field `{name}` of {width} bits does not fit unit `{unit.name}` of {unit.bits} bits at bit {unit.cursor}"
            return false
        }
        if (!empty(unit.members) && unit.members[length(unit.members) - 1].fidx + 1 != fidx) {
            errors := "c_bitfields: field `{name}` does not follow `{unit.members[length(unit.members) - 1].access.name}` in {st.name}; a unit's fields are adjacent"
            return false
        }
        unit.members |> push(BitMember(fidx = fidx, access = BitAccess(name = name, ftype = clone_type(ftype), off = unit.cursor, width = width)))
        unit.cursor += width
    }
    for (u in units) {
        if (empty(u.members)) {
            errors := "c_bitfields: unit `{u.name}` holds no field"
            return false
        }
    }
    return true
}

[structure_macro(name = "c_bitfields")]
class CBitfieldsAnnotation : AstStructureAnnotation {
    def override apply(var st : StructurePtr; var group : ModuleGroup; var args : AnnotationArgumentList; var errors : das_string) : bool {
        if (st.flags.isClass) {
            errors := "c_bitfields: {st.name} is a class; bitfields live in a struct"
            return false
        }
        var units : array<BitUnit>
        if (!read_units(st, args, units, errors)) {
            return false
        }
        if (empty(units)) {
            errors := "c_bitfields: {st.name} names no bitfield"
            return false
        }
        for (u in units) {
            let store = BitStore(field = u.name, storage = storage_of(u.storage, 0), count = u.count)
            for (m in u.members) {
                if (!add_bit_pair(st, store, m.access, st.fields[m.fidx].at, "c_bitfields", errors)) {
                    return false
                }
            }
        }
        // each unit's first field becomes its storage and the rest go, the unit furthest down
        // the struct first, so the indices of the units above it hold
        var order <- [for (ui in range(length(units))); ui]
        sort(order) <| cmp_by(-units[_].members[0].fidx)
        for (u in order) {
            let first = units[u].members[0].fidx
            for (mi in range(length(units[u].members) - 1)) {
                st.fields |> erase(units[u].members[length(units[u].members) - 1 - mi].fidx)
            }
            st.fields[first].name := units[u].name
            var unit_type = new TypeDecl(baseType = storage_of(units[u].storage, 0).base, at = st.fields[first].at)
            st.fields[first]._type = units[u].count == 0 ? unit_type : make_fixed_array_type(units[u].count, unit_type)
        }
        return true
    }
}

//! The bytes of a `uint8[k]` unit holding the word `w`, little-endian, `t` naming the unit's type
//! (`default<uint8[3]>`): the initializer of a byte unit. The type parameter is `UnitBytesT`, not
//! `T`: a generic's `auto(T)` binds a struct `T` visible where the generic is declared, its own
//! module or one it requires (`probes/test_bitfields.das`, "a generic's auto(T) binds a struct T
//! visible where the generic is declared").
def c_unit_bytes(w : uint64; t : auto(UnitBytesT)) : UnitBytesT {
    var r : UnitBytesT
    for (i in range(length(r))) {
        r[i] = uint8(w >> uint64(8 * i))
    }
    return r
}

def c_unit_bytes(w : uint; t : auto(UnitBytesT)) : UnitBytesT => c_unit_bytes(uint64(w), t)

c_runtime/c_bounds.das:
options gen2

module c_bounds public

//! `end_index(k, n)`: the index of C's `&a[k]` into an array of `n` elements, checked the way
//! das checks `a[k]` but with `n` itself allowed, since C forms the address one past the end.
//! The compare is unsigned, so a negative `k` fails as das's own range check does.
def end_index(k : auto(I); n : int) : I {
    if (uint64(k) > uint64(n)) {
        panic("index out of range, {k} of {n}")
    }
    return k
}

c_runtime/c_builtins.das:
options gen2

module c_builtins public

require c_runtime/c_exit

//! The GCC builtins with a direct das meaning, as the converter maps them (the shim list,
//! `converter/ARCHITECTURE_EMITTER.md`): the bit counts over das's own `clz`, `ctz` and `popcnt`
//! at the operand's width, which C's `l` and `ll` spellings select through the argument's type,
//! the byte swaps, the sign bit, `__builtin_unreachable` as an abort and `__builtin_prefetch`
//! as nothing but its arguments' evaluation. A count of a zero operand that C leaves undefined
//! (`clz`, `ctz`) gives das's answer.

//! `__builtin_ffs`: one plus the index of the lowest set bit, 0 for 0.
def c_ffs(x : int) : int => x == 0 ? 0 : int(ctz(uint(x))) + 1

def c_ffs(x : int64) : int => x == 0l ? 0 : int(ctz(uint64(x))) + 1

//! `__builtin_ctz`: the trailing zero bits.
def c_ctz(x : uint) : int => int(ctz(x))

def c_ctz(x : uint64) : int => int(ctz(x))

//! `__builtin_clz`: the leading zero bits.
def c_clz(x : uint) : int => int(clz(x))

def c_clz(x : uint64) : int => int(clz(x))

//! `__builtin_popcount`: the set bits.
def c_popcount(x : uint) : int => int(popcnt(x))

def c_popcount(x : uint64) : int => int(popcnt(x))

//! `__builtin_parity`: the set bits modulo 2.
def c_parity(x : uint) : int => int(popcnt(x)) & 1

def c_parity(x : uint64) : int => int(popcnt(x)) & 1

//! `__builtin_clrsb`: the leading bits after the sign bit equal to it; das's `clz` of a zero
//! operand is not the width, so a zero or minus one counts every bit but the sign
def c_clrsb(x : int) : int {
    let rest = uint(x < 0 ? ~x : x)
    return rest == 0u ? 31 : int(clz(rest)) - 1
}

def c_clrsb(x : int64) : int {
    let rest = uint64(x < 0l ? ~x : x)
    return rest == 0ul ? 63 : int(clz(rest)) - 1
}

//! `__builtin_bswap16`, `32` and `64`: the bytes in reverse order.
def c_bswap16(x : uint16) : uint16 => uint16((uint(x) >> 8u) | ((uint(x) & 0xFFu) << 8u))

def c_bswap32(x : uint) : uint => (x >> 24u) | ((x >> 8u) & 0xFF00u) | ((x << 8u) & 0xFF0000u) | (x << 24u)

def c_bswap64(x : uint64) : uint64 => (uint64(c_bswap32(uint(x))) << 32ul) | uint64(c_bswap32(uint(x >> 32ul)))

//! `__builtin_signbit`: 1 when the sign bit of `x` is set (a negative zero included), else 0.
def c_signbit(x : double) : int => int(unsafe(reinterpret<uint64>(x)) >> 63ul)

def c_signbit(x : float) : int => int(unsafe(reinterpret<uint>(x)) >> 31u)

//! `__builtin_unreachable`: reaching it is undefined in C; the run ends as `abort` ends it.
def c_unreachable {
    c_abort()
}

//! `__builtin_prefetch`: a cache hint, nothing for das to do once its arguments are evaluated;
//! `[sideeffects]` keeps the call, since das drops a call to an empty function and its arguments'
//! effects with it (probes/test_functions.das)
[sideeffects]
def c_prefetch(_addr : auto; _rw : int = 0; _locality : int = 3) {
    pass
}

c_runtime/c_do_while.das:
options gen2

module c_do_while public

require daslib/ast
require daslib/ast_boost
require daslib/macro_boost
require daslib/templates_boost

// finds a `continue` of the c_do_while's own loop: one outside every loop the body nests, an
// inner c_do_while included; a match arm's `continue` is the loop's, so blocks are walked
class private OwnContinue : AstVisitor {
    depth : int
    found : bool
    def override preVisitExprWhile(expr : ExprWhile?) {
        depth++
    }
    def override visitExprWhile(var expr : ExprWhile?) : ExpressionPtr {
        depth--
        return expr
    }
    def override preVisitExprFor(expr : ExprFor?) {
        depth++
    }
    def override visitExprFor(var expr : ExprFor?) : ExpressionPtr {
        depth--
        return expr
    }
    def override preVisitExprCallMacro(expr : ExprCallMacro?) {
        if (expr.name == "c_do_while") {
            depth++
        }
    }
    def override visitExprCallMacro(var expr : ExprCallMacro?) : ExpressionPtr {
        if (expr.name == "c_do_while") {
            depth--
        }
        return expr
    }
    def override preVisitExprContinue(expr : ExprContinue?) {
        if (depth == 0) {
            found = true
        }
    }
}

def private continues_own_loop(body : array<ExpressionPtr>) : bool {
    var scan = new OwnContinue()
    make_visitor(*scan) $(adapter) {
        for (e in body) {
            visit(e, adapter)
        }
    }
    let found = scan.found
    unsafe {
        delete scan
    }
    return found
}

//! `c_do_while (c) { body }`: C's `do { body } while (c);`, the body run once before the first test.
//! The call expands in place before its arguments are inferred, the block's statements spliced
//! into the loop, so a `break` leaves the loop, a `return` the function and a `continue` reaches
//! the test, as in C. A body with no `continue` of its own loop is
//! `while (true) { body; if (!(c)) { break } }`, otherwise
//! `var first = true; while (first || c) { first = false; body }` under a fresh name. The test
//! is a das `bool`, which the `!` or `||` of the expansion checks.
[call_macro(name = "c_do_while")]
class CDoWhileMacro : AstCallMacro {
    def override canVisitArgument(expr : ExprCallMacro?; argIndex : int) : bool => false
    def override canFoldReturnResult(expr : ExprCallMacro?) : bool => false
    def override visit(prog : ProgramPtr; mod : Module?; var expr : ExprCallMacro?) : ExpressionPtr {
        if (length(expr.arguments) != 2 || !(expr.arguments[1] is ExprMakeBlock)) {
            macro_error(prog, expr.at, "c_do_while takes a condition and a block: c_do_while (c) \{ ... \}")
            return <- default<ExpressionPtr>
        }
        let blk = (expr.arguments[1] as ExprMakeBlock)._block as ExprBlock
        if (length(blk.arguments) != 0 || !empty(blk.finalList)) {
            macro_error(prog, expr.at, "c_do_while's block takes no arguments and has no finally section")
            return <- default<ExpressionPtr>
        }
        var body <- [for (e in blk.list); clone_expression(e)]
        var cond = expr.arguments[0]
        var expansion : ExpressionPtr
        var loop : ExprWhile?
        var at = 0
        if (!continues_own_loop(body)) {
            expansion = qmacro_expr() {
                while (true) {
                    if (!($e(cond))) {
                        break
                    }
                }
            }
            loop = expansion as ExprWhile
        } else {
            let first = make_unique_private_name("_first", expr.at)
            expansion = qmacro_block() {
                var $i(first) = true
                while ($i(first) || $e(cond)) {
                    $i(first) = false
                }
            }
            loop = (expansion as ExprBlock).list[1] as ExprWhile
            at = 1
        }
        // the loop's own nodes take the call's line, the body's keep theirs; the body's statements go
        // into the loop's own block, as the spelled loop holds them
        expansion |> force_at(expr.at)
        var loop_block = loop.body as ExprBlock
        for (e in body) {
            loop_block.list |> emplace(e, at)
            at++
        }
        return <- expansion
    }
}

c_runtime/c_exit.das:
options gen2

module c_exit public

require daslib/fio
require crt
require c_runtime/c_args

//! The C process-exit protocol: `c_atexit` registers, the handlers run once in LIFO order
//! either on the normal return from `main` (the `[finalize]` walker) or inside `c_exit`,
//! which then ends the process with `exit_now` so the code reaches the parent; `c_abort`
//! ends it with code 3 and runs no handler, which is C's rule and the MSVC baseline's code. The
//! return from `main` also flushes every C stream while the context lives: a buffer the program
//! handed `setvbuf` is das memory, which libc's own flush at process exit would read freed.

var private atexit_list : array<function<() : void>>
var private atexit_ran = false

def c_atexit(f : function<() : void>) : int {
    atexit_list |> push(f)
    return 0
}

def c_run_atexit {
    if (atexit_ran) {
        return
    }
    atexit_ran = true
    var i = length(atexit_list) - 1
    while (i >= 0) {
        invoke(atexit_list[i])
        i--
    }
}

def c_exit(code : int) {
    c_run_atexit()
    unsafe(exit_now(code))
}

def c_abort {
    unsafe(exit_now(3))
}

//! glibc's `__assert_fail`, which `assert` calls without `NDEBUG` when its expression is zero:
//! glibc's message on stderr (`<program>: <file>:<line>: <function>: Assertion `<expression>'
//! failed.`, `<program>` the base name of `argv[0]` as glibc's `__progname`, and nothing before
//! the file when it is empty), then `c_abort`.
def c_assert_fail(expr, file : uint8?; line : uint; func : uint8?) {
    unsafe {
        let err = crt::c_stderr()
        var program = c_argc() > 0 ? deref(c_argv()) : null
        let slash = program != null ? crt::strrchr(program, '/') : null
        if (slash != null) {
            program = reinterpret<uint8?>(slash) + 1
        }
        if (program != null && deref(program) != uint8(0)) {
            crt::fputs(program, err)
            crt::fputs(reinterpret<uint8?>(": "), err)
        }
        crt::fputs(file, err)
        crt::fputs(reinterpret<uint8?>(":{int64(line)}: "), err)
        crt::fputs(func, err)
        crt::fputs(reinterpret<uint8?>(": Assertion `"), err)
        crt::fputs(expr, err)
        crt::fputs(reinterpret<uint8?>("' failed.\n"), err)
        crt::fflush(err)
    }
    c_abort()
}

[finalize]
def private c_shutdown {
    c_run_atexit()
    unsafe(crt::fflush(null))
}

c_runtime/c_function.das:
options gen2

module c_function public

require daslib/ast
require daslib/ast_boost
require daslib/templates_boost

//! `[c_function]`: the whole body of the function runs under one `unsafe`, so a converted C
//! body full of pointer arithmetic, `deref`, `reinterpret` and raw allocation carries no
//! per-operation wrap. The converter emits it only on functions whose body needs it.
[function_macro(name = "c_function")]
class CFunctionAnnotation : AstFunctionAnnotation {
    def override apply(var func : FunctionPtr; var group : ModuleGroup; var args : AnnotationArgumentList; var errors : das_string) : bool {
        func.body = qmacro_block() {
            unsafe {
                $e(func.body)
            }
        }
        return true
    }
}

c_runtime/c_jit_build.das:
options gen2

module c_jit_build shared

require daslib/ast_boost

//! The JIT build of a converted program: declares the program option `jit_split_modules`, dasLLVM's
//! script pin of its partitioning (`docs/probe-findings.md` F92), so an entry module requiring this
//! piece may write `options jit_split_modules = 0` and compile under every tier. dasLLVM declares
//! the option only in a program that requires `llvm/llvm_jit`, which would load the JIT compiler
//! into every tier's startup, and daslang refuses an undeclared option; the JIT reads the pin by
//! name from the entry module's options, the interpreter, the AOT host and the exe build ignore it.

[_macro, macro_function]
def private declare_jit_options {
    if (is_compiling_macros_in_module("c_jit_build")) {
        this_module() |> add_module_option("jit_split_modules", Type.tInt)
    }
}

c_runtime/c_macro.das:
options gen2

module c_macro public

require daslib/ast
require daslib/ast_boost
require daslib/templates_boost
require daslib/macro_boost

//! `[c_macro]` on a def: every call is replaced, once the call is inferred, by the def's body with
//! each parameter substituted by its argument expression as written, the textual expansion of a C
//! function-like macro. No argument copy, result temporary or lowered condition is left for the
//! interpreter. An expression body (`=> e`, also under `[c_function]`'s `unsafe`) becomes the
//! expression; a void def's statement body becomes a block in the call's place, its locals renamed
//! apart from the caller's. A body of any other shape is a compile error.

// the expansions so far in this compile; it numbers the locals a statement body declares
var private expansion_serial = 0

class private MarkSafe : AstVisitor {
    def override preVisitExpression(var expr : ExpressionPtr) : void {
        expr.genFlags.alwaysSafe = true
    }
}

// every node of `e` is flagged safe: `unsafe` of `[c_function]` does not reach a lifted expression
def private mark_safe(var e : Expression?) {
    var v = new MarkSafe()
    make_visitor(*v) $(adapter) {
        visit(e, adapter)
    }
    unsafe {
        delete v
    }
}

class private CollectLocals : AstVisitor {
    names : array<string>
    def override preVisitExprLetVariable(expr : ExprLet?; arg : VariablePtr; lastArg : bool) : void {
        names |> push(string(arg.name))
    }
    def override preVisitExprForVariable(expr : ExprFor?; svar : VariablePtr; last : bool) : void {
        names |> push(string(svar.name))
    }
}

// the names `body` declares: `let`/`var` locals and `for` iterators
def private local_names(var body : Expression?) : array<string> {
    var v = new CollectLocals()
    make_visitor(*v) $(adapter) {
        visit(body, adapter)
    }
    var names <- v.names
    unsafe {
        delete v
    }
    return <- names
}

// the def's written body: a generic instance's is its generic's
def private source_body(var fn : Function?) : Expression? {
    var src = fn
    while (src.fromGeneric != null) {
        src = src.fromGeneric
    }
    return src.body
}

// `body` without the one-statement blocks and the `unsafe` around it; `wrapped` tells whether an
// `unsafe` was taken off
def private unwrap(var body : Expression?; var wrapped : bool&) : Expression? {
    var cur = body
    while (cur != null) {
        if (cur is ExprBlock) {
            var blk = cur as ExprBlock
            if (length(blk.list) != 1 || length(blk.finalList) != 0) {
                break
            }
            let inner = blk.list[0]
            if (!(inner is ExprBlock || inner is ExprUnsafe || inner is ExprReturn)) {
                break
            }
            cur = blk.list[0]
        } elif (cur is ExprUnsafe) {
            cur = (cur as ExprUnsafe).body
            wrapped = true
        } else {
            break
        }
    }
    return cur
}

[function_macro(name = "c_macro")]
class CMacroAnnotation : AstFunctionAnnotation {
    def override transform(var expr : ExprCallFunc?; var errors : das_string) : Expression? {
        if (expr.func == null) {
            return null
        }
        var fn = expr.func
        var wrapped = false
        var body = unwrap(source_body(fn), wrapped)
        if (body == null) {
            errors := "[c_macro] {fn.name}: no body"
            return null
        }
        var res : Expression?
        if (body is ExprReturn) {
            let ret = body as ExprReturn
            if (ret.subexpr == null) {
                errors := "[c_macro] {fn.name}: a return without a value"
                return null
            }
            if (ret.subexpr is ExprConstPtr && fn.result.isPointer) {
                // a bare `null` keeps the def's result type
                res = qmacro(default<$t(fn.result)>)
            } else {
                res = clone_expression(ret.subexpr)
            }
        } elif (body is ExprBlock && fn.result.isVoid) {
            res = clone_expression(body)
            expansion_serial ++
            let names <- local_names(res)
            if (!empty(names)) {
                res = apply_template(res) $(rules) {
                    for (n in names) {
                        rules |> renameVariable(n, "_cm{expansion_serial}_{n}")
                    }
                }
            }
        } else {
            errors := "[c_macro] {fn.name}: the body is neither one expression nor a void def's statements"
            return null
        }
        if (wrapped) {
            mark_safe(res)
        }
        res = apply_template(res) $(rules) {
            for (farg, a in fn.arguments, expr.arguments) {
                rules |> replaceVariable(string(farg.name)) <| clone_expression(a)
            }
        }
        if (wrapped && res is ExprBlock) {
            res = qmacro_block() {
                unsafe {
                    $e(res)
                }
            }
        }
        res |> force_at(expr.at)
        return res
    }
}

c_runtime/c_signal.das:
options gen2

module c_signal public

require crt

//! C's `signal` in the dialect (`docs/stdlib-examples.md`, "signal.h"): a converted handler never
//! runs, since das code cannot run from a host signal, so `c_signal` keeps the handler of each
//! signal number and returns the one before it, `SIG_DFL` (the null function value) until the
//! first call. `SIG_IGN` and `SIG_DFL` are applied to the host process for real, so a signal the
//! program ignores (`SIGPIPE`) does not end it; a signal the host delivers to a number with a
//! converted handler takes the host's disposition. A number the dialect's C library refuses
//! returns `SIG_ERR` with `errno` EINVAL.

//! C's `void (*)(int)`, as the converter spells a handler.
typedef CSignalHandler = function<(sig : int) : void>

//! The signal numbers a handler is kept for, 1 to 64: glibc's `_NSIG` is 65, msvc's `NSIG` 23.
let C_SIGNAL_LIMIT = 65

//! `SIG_IGN` and `SIG_ERR` as the emitter spells them, the integer sentinels a function value
//! holds: `(void (*)(int)) 1` and `(void (*)(int)) -1`.
let C_SIG_IGN_BITS = 1ul
let C_SIG_ERR_BITS = 0xfffffffffffffffful

//! C's EINVAL, 22 under both dialects.
let C_EINVAL = 22

//! The dialect's C library is msvc's, whose signal numbers are its own: the converted module's
//! dialect `[init]` sets it.
var c_signal_msvc = false

var private handlers : CSignalHandler[C_SIGNAL_LIMIT]

// glibc refuses SIGKILL (9), SIGSTOP (19) and the two numbers its threads reserve (32, 33); msvc
// knows SIGINT, SIGILL, SIGABRT_COMPAT, SIGFPE, SIGSEGV, SIGTERM, SIGBREAK and SIGABRT
def private accepted(sig : int) : bool {
    if (c_signal_msvc) {
        return sig == 2 || sig == 4 || sig == 6 || sig == 8 || sig == 11 || sig == 15 || sig == 21 || sig == 22
    }
    return sig >= 1 && sig < C_SIGNAL_LIMIT && sig != 9 && sig != 19 && sig != 32 && sig != 33
}

// the host's number of the dialect's signal `sig`, 0 for one the host has none of: msvc's SIGABRT
// is 22 and its SIGBREAK 21, where linux numbers SIGTTOU and SIGTTIN
def private host_signal(sig : int) : int {
    if (!c_signal_msvc) {
        return sig
    }
    return sig == 22 ? 6 : (sig == 21 ? 0 : sig)
}

def c_signal(sig : int; handler : CSignalHandler) : CSignalHandler {
    if (!accepted(sig)) {
        crt::c_set_errno(C_EINVAL)
        return unsafe(reinterpret<CSignalHandler>(C_SIG_ERR_BITS))
    }
    let bits = unsafe(reinterpret<uint64>(handler))
    let host = host_signal(sig)
    if (host != 0 && (bits == 0ul || bits == C_SIG_IGN_BITS)) {
        crt::c_signal_host(host, bits == C_SIG_IGN_BITS)
    }
    let previous = handlers[sig]
    handlers[sig] = handler
    return previous
}

c_runtime/c_sort.das:
options gen2

module c_sort public

//! C's `qsort` and `bsearch` over raw bytes, in C's own signatures: `n` elements of `size`
//! bytes each from `base`, ordered by the converted C comparator, which takes the two element
//! addresses as C declares them. The CRT's own `qsort` cannot call back into das, so `qsort` is
//! the runtime's byte sort (`__builtin_sort_any_cblock`, the engine under daslib's `sort`) with
//! the comparator in a block; it is unstable, as C allows. `bsearch` is a binary search.

//! The comparator C passes to `qsort` and `bsearch`: `int cmp(const void *, const void *)`
//! as the converter spells a function pointer, every data pointer position `var`.
typedef CCompare = function<(var a : void?; var b : void?) : int>

// the runtime's sort counts elements and bytes in `int`
let private SORT_LIMIT = 0x7fffffffu

//! C's `qsort`: sorts `n` elements of `size` bytes from `base` in place, by `cmp`.
def c_qsort(base : void?; n : uint64; size : uint64; cmp : CCompare) {
    if (n < 2ul) {
        return
    }
    if (n > uint64(SORT_LIMIT) || size > uint64(SORT_LIMIT)) {
        panic("c_qsort: {n:d} elements of {size:d} bytes exceed the runtime sort's int counts")
    }
    __builtin_sort_any_cblock(base, int(size), int(n)) $(var a, b : void?) : bool {
        return invoke(cmp, a, b) < 0
    }
}

// the address of element `i`
def private element_at(base : uint8?; i : int64; size : uint64) : void? {
    let at = unsafe(base + int64(uint64(i) * size))
    return unsafe(reinterpret<void?>(at))
}

//! C's `bsearch`: the address of an element of the `n` sorted ones from `base` that `cmp`
//! finds equal to `key`, called as `cmp(key, element)`; `null` when none is.
def c_bsearch(var key : void?; base : void?; n : uint64; size : uint64; cmp : CCompare) : void? {
    let bytes = unsafe(reinterpret<uint8?>(base))
    var lo = 0l
    var hi = int64(n)
    while (lo < hi) {
        let mid = lo + (hi - lo) / 2l
        var elem = element_at(bytes, mid, size)
        let r = invoke(cmp, key, elem)
        if (r == 0) {
            return elem
        }
        if (r < 0) {
            hi = mid
        } else {
            lo = mid + 1l
        }
    }
    return null
}

c_runtime/c_storage.das:
options gen2

module c_storage public

require daslib/ast
require daslib/ast_boost
require daslib/templates_boost
require daslib/macro_boost

//! The unsigned storage types the C-layout annotations lay data out in: `[c_bitfields]` units and
//! `[c_union]` storage. Each is 1, 2, 4 or 8 bytes, aligned to its size. Also the bit arithmetic
//! both annotations generate: the property pair of one bitfield over the storage that holds it.

//! One storage type: its das name, its size in bytes (its alignment too), its width in bits
//! and its das base type.
struct CStorage {
    name : string
    bytes : int
    bits : int
    base : Type
}

//! The four storage types, narrowest first.
let C_STORAGES = fixed_array(CStorage(name = "uint8", bytes = 1, bits = 8, base = Type.tUInt8), CStorage(name = "uint16", bytes = 2, bits = 16, base = Type.tUInt16), CStorage(name = "uint", bytes = 4, bits = 32, base = Type.tUInt), CStorage(name = "uint64", bytes = 8, bits = 64, base = Type.tUInt64))

//! The storage type named `name`, or the one `bits` wide when `name` is empty; an empty name
//! when there is none.
def storage_of(name : string; bits : int) : CStorage {
    for (st in C_STORAGES) {
        if (empty(name) ? st.bits == bits : st.name == name) {
            return st
        }
    }
    return CStorage()
}

//! The storage type `bytes` wide, which is its alignment too; an empty name when there is none.
def storage_of_bytes(bytes : int) : CStorage {
    for (st in C_STORAGES) {
        if (st.bytes == bytes) {
            return st
        }
    }
    return CStorage()
}

//! The index of field `name` in struct `st`, -1 when it has none.
def field_index(st : StructurePtr; name : string) : int {
    for (idx in range(length(st.fields))) {
        if (st.fields[idx].name == name) {
            return idx
        }
    }
    return -1
}

//! Where a bitfield's bits live: the struct field `field`, a scalar of `storage` when `count` is
//! 0, else an array of `storage` whose first `count` elements hold the bits, little-endian.
struct BitStore {
    field : string
    storage : CStorage
    count : int
}

//! One bitfield: its name, its declared das type, and its bit offset and width in the store.
struct BitAccess {
    name : string
    ftype : TypeDeclPtr
    off : int
    width : int
}

// the arithmetic a store's bits take: `uint` up to 32 of them, `uint64` past, since das defines
// no shift on the 8- and 16-bit storage types
struct private Arith {
    bits : int
    wide : bool
    name : string
}

def private arith_of(b : BitStore) : Arith {
    let wide = (b.count == 0 ? b.storage.bits : b.storage.bits * b.count) > 32
    return Arith(bits = wide ? 64 : 32, wide = wide, name = wide ? "uint64" : "uint")
}

// a constant of the arithmetic type
def private arith_const(a : Arith; v : uint64) : ExpressionPtr => a.wide ? qmacro($v(v)) : qmacro($v(uint(v)))

def private low_mask(width : int) : uint64 => width >= 64 ? ~0ul : (1ul << uint64(width)) - 1ul

// the store read in the arithmetic type: the field, or its elements assembled little-endian
def private store_read(b : BitStore; a : Arith) : ExpressionPtr {
    if (b.count == 0) {
        var read = qmacro(s.$f(b.field))
        return b.storage.name == a.name ? read : qmacro($c(a.name)($e(read)))
    }
    var e : ExpressionPtr
    for (i in range(b.count)) {
        var elem = qmacro(s.$f(b.field)[$v(i)])
        if (b.storage.name != a.name) {
            elem = qmacro($c(a.name)($e(elem)))
        }
        if (i > 0) {
            elem = qmacro($e(elem) << $e(arith_const(a, uint64(i * b.storage.bits))))
        }
        e = i == 0 ? elem : qmacro($e(e) | $e(elem))
    }
    return e
}

//! `operator . name` of bitfield `m` over store `b`, reported at `at` (the member's
//! declaration): shift and mask, a signed field shifting its top bit to the word's top and back,
//! which sign-extends.
def bit_getter(var st : StructurePtr; b : BitStore; m : BitAccess; at : LineInfo) : FunctionPtr {
    let a = arith_of(b)
    let t_name = describe(m.ftype)
    var e = store_read(b, a)
    if (m.ftype.isSignedInteger) {
        let up = a.bits - m.off - m.width
        if (up > 0) {
            e = qmacro($e(e) << $e(arith_const(a, uint64(up))))
        }
        let signed_name = a.wide ? "int64" : "int"
        e = qmacro($c(signed_name)($e(e)))
        if (a.bits - m.width > 0) {
            e = a.wide ? qmacro($e(e) >> $v(int64(a.bits - m.width))) : qmacro($e(e) >> $v(a.bits - m.width))
        }
        if (t_name != signed_name) {
            e = qmacro($c(t_name)($e(e)))
        }
    } else {
        if (m.off > 0) {
            e = qmacro($e(e) >> $e(arith_const(a, uint64(m.off))))
        }
        if (m.width < a.bits) {
            e = qmacro($e(e) & $e(arith_const(a, low_mask(m.width))))
        }
        if (m.ftype.isBool) {
            e = qmacro($e(e) != $e(arith_const(a, 0ul)))
        } elif (t_name != a.name) {
            e = qmacro($c(t_name)($e(e)))
        }
    }
    var fn <- qmacro_function(".`{m.name}") $(s : $t(st)) : $t(m.ftype) {
        return $e(e)
    }
    fn.flags.generated = true
    fn.at = at
    return <- fn
}

//! `operator . name :=` of bitfield `m` over store `b`, reported at `at`: clears the field's bits
//! and ors the masked value in, the word narrowing back into the store, one element at a time
//! for an array.
def bit_setter(var st : StructurePtr; b : BitStore; m : BitAccess; at : LineInfo) : FunctionPtr {
    let a = arith_of(b)
    let mask = low_mask(m.width)
    var v = qmacro(v)
    if (m.ftype.isBool) {
        v = qmacro($e(v) ? $e(arith_const(a, 1ul)) : $e(arith_const(a, 0ul)))
    } elif (describe(m.ftype) != a.name) {
        v = qmacro($c(a.name)($e(v)))
    }
    if (m.width < a.bits) {
        v = qmacro($e(v) & $e(arith_const(a, mask)))
    }
    if (m.off > 0) {
        v = qmacro($e(v) << $e(arith_const(a, uint64(m.off))))
    }
    let keep_mask = ~(mask << uint64(m.off)) & low_mask(a.bits)
    var e = qmacro(($e(store_read(b, a)) & $e(arith_const(a, keep_mask))) | $e(v))
    var body : array<ExpressionPtr>
    body |> reserve(b.count + 1)
    if (b.count == 0) {
        if (b.storage.name != a.name) {
            e = qmacro($c(b.storage.name)($e(e)))
        }
        body |> push <| qmacro_expr() {
            s.$f(b.field) = $e(e)
        }
    } else {
        body |> push <| qmacro_expr() {
            let w = $e(e)
        }
        for (i in range(b.count)) {
            var part = i == 0 ? qmacro(w) : qmacro(w >> $e(arith_const(a, uint64(i * b.storage.bits))))
            if (b.storage.name != a.name) {
                part = qmacro($c(b.storage.name)($e(part)))
            }
            body |> push <| qmacro_expr() {
                s.$f(b.field)[$v(i)] = $e(part)
            }
        }
    }
    var fn <- qmacro_function(".`{m.name}`clone") $(var s : $t(st); v : $t(m.ftype)) : void {
        $b(body)
    }
    // a `v : T` parameter is `T const`, as the parser makes it, so a hand-written twin collides
    fn.arguments[1]._type.flags.constant = true
    fn.flags.generated = true
    fn.at = at
    return <- fn
}

//! Adds the property pair of bitfield `m` over store `b`, declared at `at`, to the module being
//! compiled; false with `errors` set, prefixed by `annotation`, when the module already has
//! either operator.
def add_bit_pair(var st : StructurePtr; b : BitStore; m : BitAccess; at : LineInfo; annotation : string; var errors : das_string) : bool {
    var getter <- bit_getter(st, b, m, at)
    if (!(compiling_module() |> add_function(getter))) {
        errors := "{annotation}: {st.name} already has `operator . {m.name}`"
        return false
    }
    var setter <- bit_setter(st, b, m, at)
    if (!(compiling_module() |> add_function(setter))) {
        errors := "{annotation}: {st.name} already has `operator . {m.name} :=`"
        return false
    }
    return true
}

c_runtime/c_switch.das:
options gen2

module c_switch public

require daslib/ast
require daslib/ast_boost
require daslib/macro_boost
require daslib/templates_boost

// one `case (v, ...) { body }` arm: `_` among the values is `default`
struct private Arm {
    values : array<ExpressionPtr>
    is_default : bool
    body : array<ExpressionPtr>
}

// the `break` and `continue` of the switch's own level: outside every loop and inner do_while the
// arms nest; an own `continue` becomes `cont = true; break` when `cont` is set, the epilogue after
// the switch's loop continuing the real one
class private OwnJumps : AstVisitor {
    depth : int
    breaks : bool
    continues : bool
    cont : string
    def override preVisitExprWhile(expr : ExprWhile?) {
        depth++
    }
    def override visitExprWhile(var expr : ExprWhile?) : ExpressionPtr {
        depth--
        return expr
    }
    def override preVisitExprFor(expr : ExprFor?) {
        depth++
    }
    def override visitExprFor(var expr : ExprFor?) : ExpressionPtr {
        depth--
        return expr
    }
    def override preVisitExprCallMacro(expr : ExprCallMacro?) {
        if (expr.name == "c_do_while") {
            depth++
        }
    }
    def override visitExprCallMacro(var expr : ExprCallMacro?) : ExpressionPtr {
        if (expr.name == "c_do_while") {
            depth--
        }
        return expr
    }
    def override preVisitExprBreak(expr : ExprBreak?) {
        breaks ||= depth == 0
    }
    def override preVisitExprContinue(expr : ExprContinue?) {
        continues ||= depth == 0
    }
    def override visitExprBlock(var expr : ExprBlock?) : ExpressionPtr {
        if (depth != 0 || empty(cont) || !has_value([for (e in expr.list); e is ExprContinue], true)) {
            return expr
        }
        var list : array<ExpressionPtr>
        for (e in expr.list) {
            if (e is ExprContinue) {
                var stmt = qmacro_expr() {
                    $i(cont) = true
                }
                list |> push(at_call(stmt, e.at))
                list |> push(new ExprBreak(at = e.at))
            } else {
                list |> push(e)
            }
        }
        expr.list |> clear()
        for (e in list) {
            expr.list |> push(e)
        }
        return expr
    }
}

// expands every inner switch first, innermost out, so an arm's own jumps are plain loops and
// blocks when the outer one scans them
class private InnerSwitches : AstVisitor {
    failed : bool
    def override visitExprCallMacro(var expr : ExprCallMacro?) : ExpressionPtr {
        if (expr.name != "c_switch") {
            return expr
        }
        var expansion = expand_switch(expr)
        if (expansion == null) {
            failed = true
            return expr
        }
        return expansion
    }
}

// finds a `case` call left inside an arm once the inner switches are expanded: a case label in a
// nested block of an arm, C's Duff's device, which the macro does not take
class private StrayCase : AstVisitor {
    found : bool
    at : LineInfo = LineInfo()
    def override preVisitExprCall(expr : ExprCall?) {
        if (!found && expr.name == "case") {
            found = true
            at = expr.at
        }
    }
}

// visits each arm's statements as a block of their own, so that an arm's own `continue` is a block's
def private visit_arms(var arms : array<Arm>; adapter : VisitorAdapter?) {
    for (arm in arms) {
        var blk = visit(block_of(LineInfo(), arm.body), adapter) as ExprBlock
        arm.body |> clear()
        for (e in blk.list) {
            arm.body |> push(e)
        }
    }
}

// the jumps of the arms' statements; `cont` set rewrites the own continues
def private own_jumps(var arms : array<Arm>; cont : string; var breaks, continues : bool&) {
    var scan = new OwnJumps(cont = cont)
    make_visitor(*scan) $(adapter) {
        visit_arms(arms, adapter)
    }
    breaks = scan.breaks
    continues = scan.continues
    unsafe {
        delete scan
    }
}

// the arms of the switch's block, inner switches expanded; false with the error set
def private parse_arms(expr : ExprCallMacro?; var arms : array<Arm>) : bool {
    let blk = (expr.arguments[1] as ExprMakeBlock)._block as ExprBlock
    if (length(blk.arguments) != 0 || !empty(blk.finalList)) {
        macro_error(compiling_program(), expr.at, "switch's block takes no arguments and has no finally section")
        return false
    }
    var seen : table<string>
    for (st in blk.list) {
        let call = st is ExprCall ? st as ExprCall : null
        if (call == null || call.name != "case" || length(call.arguments) < 2 || !(call.arguments[length(call.arguments) - 1] is ExprMakeBlock)) {
            macro_error(compiling_program(), st.at, "c_switch holds only arms: case (v, ...) \{ ... \}, `_` the default")
            return false
        }
        var arm : Arm
        let n = length(call.arguments) - 1
        for (idx in range(n)) {
            let v = call.arguments[idx]
            // a case value is a constant (C requires it), so comparing its text finds a duplicate
            let is_default = v is ExprVar && (v as ExprVar).name == "_"
            let key = is_default ? "_" : describe(v)
            if (key_exists(seen, key)) {
                macro_error(compiling_program(), v.at, "c_switch: duplicate case value {key}")
                return false
            }
            seen |> insert(key)
            if (is_default) {
                arm.is_default = true
            } else {
                arm.values |> push(clone_expression(v))
            }
        }
        let body = (call.arguments[n] as ExprMakeBlock)._block as ExprBlock
        for (e in body.list) {
            arm.body |> push(clone_expression(e))
        }
        arms |> emplace(arm)
    }
    return expand_inner(arms)
}

// the arms' inner switches expanded, innermost first; false with the error set, a case left in a
// nested block of an arm (Duff's device) among the errors
def private expand_inner(var arms : array<Arm>) : bool {
    var inner = new InnerSwitches()
    make_visitor(*inner) $(adapter) {
        visit_arms(arms, adapter)
    }
    let failed = inner.failed
    unsafe {
        delete inner
    }
    if (failed) {
        return false
    }
    var stray = new StrayCase()
    make_visitor(*stray) $(adapter) {
        visit_arms(arms, adapter)
    }
    let found = stray.found
    let at = stray.at
    unsafe {
        delete stray
    }
    if (found) {
        macro_error(compiling_program(), at, "c_switch: a case inside a nested block of an arm (Duff's device) is not supported; the converter spells such a switch open")
    }
    return !found
}

// expression `e` placed at the call's line
def private at_call(var e : ExpressionPtr; at : LineInfo) : ExpressionPtr {
    e |> force_at(at)
    return e
}

// `a || b || ...` of the tests, left to right as the spelled chain groups them
def private any_of(tests : array<ExpressionPtr>; at : LineInfo) : ExpressionPtr {
    var acc = clone_expression(tests[0])
    for (idx in range(1, length(tests))) {
        let t = tests[idx]
        acc = at_call(qmacro($e(acc) || $e(t)), at)
    }
    return acc
}

// `c == v` for each value, each with its own copy of `c` and `v` (the splice clones)
def private value_tests(c : ExpressionPtr; values : array<ExpressionPtr>; at : LineInfo) : array<ExpressionPtr> => <- [for (v in values); at_call(qmacro($e(c) == $e(v)), at)]

// whether control cannot run past the end of statements `body` into the next arm: they end in a
// `break`, `return`, `continue` or `goto`, a trailing block looked through
def private ends(body) : bool {
    if (empty(body)) {
        return false
    }
    let last = body[length(body) - 1]
    if (last is ExprBlock) {
        return ends((last as ExprBlock).list)
    }
    return last is ExprBreak || last is ExprReturn || last is ExprContinue || last is ExprGoto
}

// statements `body` without their tail `break`, a trailing block looked through
def private drop_tail_break(var body : array<ExpressionPtr>) {
    if (empty(body)) {
        return
    }
    let n = length(body) - 1
    if (body[n] is ExprBreak) {
        body |> erase(n)
    } elif (body[n] is ExprBlock) {
        var inner <- [for (e in (body[n] as ExprBlock).list); e]
        drop_tail_break(inner)
        (body[n] as ExprBlock).list |> clear()
        for (e in inner) {
            (body[n] as ExprBlock).list |> push(e)
        }
    }
}

// a block holding `stmts`, the arm's body
def private block_of(at : LineInfo; var stmts : array<ExpressionPtr>) : ExprBlock? {
    var blk = new ExprBlock(at = at)
    for (e in stmts) {
        blk.list |> push(e)
    }
    return blk
}

// no arm falls into the next and none breaks but at its tail, which is gone: the if-chain,
// `default` its `else`
def private if_chain(at : LineInfo; c : ExpressionPtr; var arms : array<Arm>) : ExpressionPtr {
    var otherwise : ExpressionPtr
    var chain : array<ExprIfThenElse?>
    for (arm in arms) {
        if (arm.is_default) {
            otherwise = block_of(at, arm.body)
        } else {
            let tests <- value_tests(c, arm.values, at)
            chain |> push(new ExprIfThenElse(at = at, cond = any_of(tests, at), if_true = block_of(at, arm.body)))
        }
    }
    if (empty(chain)) {
        return otherwise
    }
    for (idx in range(length(chain) - 1)) {
        chain[idx].if_false = chain[idx + 1]
    }
    chain[length(chain) - 1].if_false = otherwise
    return chain[0]
}

// the matched-flag loop, the arms as written: an arm the arm before cannot enter and that cannot
// enter the next (or is the last) tests its values in its own `if`; any other sets `flag` from its
// values and runs while it is set, so falling into the next keeps it set; the loop's own `break`
// follows the last
def private flag_loop(at : LineInfo; c : ExpressionPtr; var arms : array<Arm>) : ExpressionPtr {
    let flag = make_unique_private_name("_flag", at)
    var all_tests : array<ExpressionPtr>
    for (arm in arms) {
        var tests <- value_tests(c, arm.values, at)
        all_tests |> push_from(tests)
    }
    let count = length(arms)
    let plain <- [for (idx in range(count)); !empty(arms[idx].body) && !(arms[idx].is_default && empty(all_tests)) && (idx == 0 || ends(arms[idx - 1].body)) && (idx == count - 1 || ends(arms[idx].body))]
    var list : array<ExpressionPtr>
    // an empty arm but the last still sets the flag its values match, for the arm it falls into
    let flagged <- [for (idx in range(count)); !plain[idx] && (!empty(arms[idx].body) || idx < count - 1)]
    if (has_value(flagged, true)) {
        var stmt = qmacro_expr() {
            var $i(flag) = false
        }
        list |> push(at_call(stmt, at))
    }
    for (idx in range(count)) {
        if (!flagged[idx] && !plain[idx]) {
            continue
        }
        var tests <- value_tests(c, arms[idx].values, at)
        if (arms[idx].is_default && !empty(all_tests)) {
            let none_of = any_of(all_tests, at)
            tests |> push(at_call(qmacro(!($e(none_of))), at))
        }
        if (plain[idx]) {
            list |> push(new ExprIfThenElse(at = at, cond = any_of(tests, at), if_true = block_of(at, arms[idx].body)))
            continue
        }
        list |> reserve(length(list) + length(tests) + 2)
        for (t in tests) {
            var stmt = qmacro_expr() {
                $i(flag) ||= $e(t)
            }
            list |> push(at_call(stmt, at))
        }
        if (arms[idx].is_default && empty(all_tests)) {
            var stmt = qmacro_expr() {
                $i(flag) = true
            }
            list |> push(at_call(stmt, at))
        }
        if (!empty(arms[idx].body)) {
            list |> push(new ExprIfThenElse(at = at, cond = at_call(qmacro($i(flag)), at), if_true = block_of(at, arms[idx].body)))
        }
    }
    list |> push(new ExprBreak(at = at))
    var loop = qmacro_expr() {
        while (true) {
            break
        }
    }
    loop |> force_at(at)
    var loop_block = (loop as ExprWhile).body as ExprBlock
    loop_block.list |> clear()
    for (e in list) {
        loop_block.list |> push(e)
    }
    return loop
}

// the expansion of one switch call, null with the error set
def private expand_switch(var expr : ExprCallMacro?) : ExpressionPtr {
    let at = expr.at
    if (length(expr.arguments) != 2 || !(expr.arguments[1] is ExprMakeBlock)) {
        macro_error(compiling_program(), at, "c_switch takes a value and a block of arms: c_switch (x) \{ case (1) \{ ... \} \}")
        return null
    }
    var arms : array<Arm>
    if (!parse_arms(expr, arms)) {
        return null
    }
    // the if-chain's arms: each without its tail `break`, which must leave no other own `break`
    var chain_arms : array<Arm>
    chain_arms |> reserve(length(arms))
    for (arm in arms) {
        var copy : Arm
        copy.is_default = arm.is_default
        copy.values := arm.values
        copy.body |> reserve(length(arm.body))
        for (e in arm.body) {
            copy.body |> push(clone_expression(e))
        }
        drop_tail_break(copy.body)
        chain_arms |> emplace(copy)
    }
    var breaks, continues : bool
    own_jumps(chain_arms, "", breaks, continues)
    let looped = breaks || has_value([for (idx in range(length(arms) - 1)); !ends(arms[idx].body)], true)
    let cont = looped && continues ? make_unique_private_name("_cont", at) : ""
    if (!empty(cont)) {
        own_jumps(arms, cont, breaks, continues)
    }
    // the value is read once: a variable in place, since no arm's store into it reaches a test
    // that decides (an arm runs only once its values or the arm entering it matched), any other
    // value through a `let`
    var value = expr.arguments[0]
    let bound = !(value is ExprVar)
    let name = bound ? make_unique_private_name("_cond", at) : ""
    let c = bound ? at_call(qmacro($i(name)), at) : value
    var dispatch = looped ? flag_loop(at, c, arms) : if_chain(at, c, chain_arms)
    if (!bound && empty(cont)) {
        if (dispatch == null) {
            return new ExprBlock(at = at)
        }
        return dispatch
    }
    var outer = new ExprBlock(at = at)
    if (bound) {
        var stmt = qmacro_expr() {
            let $i(name) = $e(value)
        }
        outer.list |> push(at_call(stmt, at))
    }
    if (!empty(cont)) {
        var stmt = qmacro_expr() {
            var $i(cont) = false
        }
        outer.list |> push(at_call(stmt, at))
    }
    if (dispatch != null) {
        outer.list |> push(dispatch)
    }
    if (!empty(cont)) {
        var stmt = qmacro_expr() {
            if ($i(cont)) {
                continue
            }
        }
        outer.list |> push(at_call(stmt, at))
    }
    return outer
}

//! `c_switch (x) { case (A, B) { body } ... case (_) { body } }`: C's switch with C's meaning, `_`
//! the `default` (alone or beside values) at any position. An arm that does not end in `break`,
//! `return`, `continue` or `goto` falls into the next; a `break` of the switch's own level (outside
//! every loop and inner `c_do_while`) leaves it, a `continue` reaches the enclosing loop, and `x` is
//! read once. The call expands in place before its arguments are inferred, inner switches first:
//! with no arm falling into the next and no own `break` but an arm's tail, to
//! `if (x == A || x == B) { body } elif ... else { default }`, the tail breaks dropped; otherwise to
//! the matched-flag loop `while (true) { var flag = false; flag ||= x == A; if (flag) { body } ...
//! break }`, in which an arm neither entered nor entering tests its values in its own `if`, and an
//! own `continue` sets a flag and leaves the loop, continuing after it. A duplicate case value, a
//! second `_` and a statement that is no arm are compile errors.
[call_macro(name = "c_switch")]
class CSwitchMacro : AstCallMacro {
    def override canVisitArgument(expr : ExprCallMacro?; argIndex : int) : bool => false
    def override canFoldReturnResult(expr : ExprCallMacro?) : bool => false
    def override visit(prog : ProgramPtr; mod : Module?; var expr : ExprCallMacro?) : ExpressionPtr => <- expand_switch(expr)
}

c_runtime/c_union.das:
options gen2

module c_union public

require daslib/ast
require daslib/ast_boost
require daslib/templates_boost
require daslib/macro_boost
require daslib/math_boost
require c_runtime/c_storage

//! C unions over das storage. `[c_union] struct Value { gc : GCObject?; p : void?; n : double; i : int64 }`
//! is written C-shaped; the annotation replaces the members with one storage field
//! `_storage : U[k]`, `U` the unsigned type of the union's alignment and `k` its size over that
//! alignment, and generates per member `operator . name` twice: over a `var` union a reference
//! into the storage (read, store, compound store, `++`, a nested field, `addr`), over a const one
//! the value. `[c_union(size = N, align = A)]` states the size and alignment; the bare form
//! derives them from the members, which takes every member's type known when the struct is
//! parsed. Every member's size and alignment are checked against the storage at inference. A
//! member named with a width, `[c_union(f0 = 8)]`, is a bitfield at bit 0: its property pair,
//! `operator . f0` and `operator . f0 :=`, reads and writes the storage's leading elements as
//! one word (`c_storage`'s arithmetic), since bits are not addressable.

// whether das knows the size of a value of type `t` while the struct is parsed: every type held
// by value resolved, every dimension folded; a pointer or a function value is pointer-sized
// whatever it points at
def private size_known_at_parse(t : TypeDeclPtr) : bool {
    if (t.baseType == Type.tPointer || t.baseType == Type.tFunction) {
        return true
    }
    if (t.baseType == Type.tFixedArray) {
        return t.fixedDim > 0 && size_known_at_parse(t.firstType)
    }
    if (t.baseType == Type.tStructure) {
        for (f in t.structType.fields) {
            if (!size_known_at_parse(f._type)) {
                return false
            }
        }
        return true
    }
    return !t.isAutoOrAlias
}

// the size and alignment the members give, the size rounded up to the alignment; `size` is 0
// when a member's type is not known yet (`size_known_at_parse`)
def private member_layout(st : StructurePtr) : tuple<size : int; align : int> {
    var size = 0
    var align = 1
    for (f in st.fields) {
        if (!size_known_at_parse(f._type)) {
            return (size = 0, align = 1)
        }
        size = max(size, f._type.sizeOf)
        align = max(align, f._type.alignOf)
    }
    return (size = round_up(size, align), align = align)
}

// the integer argument `name` into `value`, -1 when absent; false with `errors` set when it is
// not an integer
def private int_arg(args : AnnotationArgumentList; name : string; var value : int&; var errors : das_string) : bool {
    let arg = find_arg(args, name)
    if (arg is nothing) {
        value = -1
        return true
    }
    if (!(arg is tInt)) {
        errors := "c_union: `{name}` is not an integer"
        return false
    }
    value = arg as tInt
    return true
}

// the width argument of member `f`, `nothing` when it is no bitfield; `size` and `align` are
// never widths
def private width_of(args : AnnotationArgumentList; f : FieldDeclaration) : RttiValue {
    if (f.name == "size" || f.name == "align") {
        return RttiValue_nothing()
    }
    return find_arg(args, string(f.name))
}

// bitfield member `f` of `width` bits at bit 0: its property pair over the storage elements
// that hold the width, the `c_storage` arithmetic; false with `errors` set when the member's
// type holds no bitfield, a `bool` is not 1 bit wide, the width is below 1 or past the type's
// bits or the storage's bytes, or the pair collides
def private add_member_bits(var st : StructurePtr; f : FieldDeclaration; width, size : int; storage : CStorage; var errors : das_string) : bool {
    if (!(f._type.isInteger || f._type.isBool)) {
        errors := "c_union: bitfield `{f.name}` is of type {describe(f._type)}, not an integer or bool"
        return false
    }
    if (f._type.isBool && width != 1) {
        errors := "c_union: bool bitfield `{f.name}` is 1 bit wide, not {width}"
        return false
    }
    if (width < 1) {
        errors := "c_union: bitfield `{f.name}` of {width} bits holds no bit"
        return false
    }
    if (width > f._type.sizeOf * 8) {
        errors := "c_union: bitfield `{f.name}` of {width} bits does not fit its type {describe(f._type)}"
        return false
    }
    let count = (width + storage.bits - 1) / storage.bits
    if (count * storage.bytes > size) {
        errors := "c_union: bitfield `{f.name}` needs {count * storage.bytes} bytes, the storage has {size}"
        return false
    }
    let store = BitStore(field = "_storage", storage = storage, count = count)
    return add_bit_pair(st, store, BitAccess(name = string(f.name), ftype = clone_type(f._type), off = 0, width = width), f.at, "c_union", errors)
}

// the shape the annotation takes: a struct with at least one member, none named `_storage`,
// none with an initializer; false with `errors` set
def private check_shape(st : StructurePtr; var errors : das_string) : bool {
    if (st.flags.isClass) {
        errors := "c_union: {st.name} is a class; a union is a struct"
        return false
    }
    if (empty(st.fields)) {
        errors := "c_union: {st.name} has no member"
        return false
    }
    for (f in st.fields) {
        if (f.name == "_storage") {
            errors := "c_union: {st.name} has a member named `_storage`, the name of the storage field"
            return false
        }
        if (f.init != null) {
            errors := "c_union: member `{f.name}` has an initializer; a union starts at zero"
            return false
        }
    }
    return true
}

// the union's size and alignment: the arguments when given, else derived from the members;
// false with `errors` set on arguments the storage cannot spell
def private layout(st : StructurePtr; args : AnnotationArgumentList; var size : int&; var align : int&; var errors : das_string) : bool {
    for (a in args) {
        if (a.name != "size" && a.name != "align" && field_index(st, string(a.name)) < 0) {
            errors := "c_union: unknown argument `{a.name}`; expecting `size`, `align` and a member's bit width"
            return false
        }
    }
    if (!int_arg(args, "size", size, errors) || !int_arg(args, "align", align, errors)) {
        return false
    }
    if ((size < 0) != (align < 0)) {
        errors := "c_union: {st.name} gives one of `size` and `align`; give both or neither"
        return false
    }
    if (size < 0) {
        let derived = member_layout(st)
        if (derived.size == 0) {
            errors := "c_union: a member type of {st.name} is not known where it is declared; state `size` and `align`"
            return false
        }
        size = derived.size
        align = derived.align
    }
    if (empty(storage_of_bytes(align).name)) {
        errors := "c_union: alignment {align} of {st.name} is not 1, 2, 4 or 8"
        return false
    }
    if (size <= 0 || size % align != 0) {
        errors := "c_union: size {size} of {st.name} is not a positive multiple of its alignment {align}"
        return false
    }
    return true
}

// `operator . name`: over a `var` union (`by_ref`) a reference into the storage, over a const
// one the value; each after the inference-time check that the member fits the storage
def private make_operator(var st : StructurePtr; f : FieldDeclaration; size, align : int; by_ref : bool) : FunctionPtr {
    let message = "c_union: member `{f.name}` of {st.name} does not fit the storage of size {size} and alignment {align}"
    var fn <- qmacro_function(".`{f.name}") $(var s : $t(st)) : $t(f._type) {
        static_assert(typeinfo sizeof(type<$t(f._type)>) <= $v(size) && typeinfo alignof(type<$t(f._type)>) <= $v(align), $v(message))
        unsafe {
            return *addr<$t(f._type)?>(s._storage)
        }
    }
    if (by_ref) {
        fn.result.flags.ref = true
    } else {
        // a `s : T` parameter is `T const`, as the parser makes it
        fn.arguments[0]._type.flags.constant = true
    }
    fn.flags.generated = true
    fn.at = f.at
    return <- fn
}

[structure_macro(name = "c_union")]
class CUnionAnnotation : AstStructureAnnotation {
    def override apply(var st : StructurePtr; var group : ModuleGroup; var args : AnnotationArgumentList; var errors : das_string) : bool {
        if (!check_shape(st, errors)) {
            return false
        }
        var size, align : int
        if (!layout(st, args, size, align, errors)) {
            return false
        }
        let storage = storage_of_bytes(align)
        for (f in st.fields) {
            let width_arg = width_of(args, f)
            if (!(width_arg is nothing)) {
                if (!(width_arg is tInt)) {
                    errors := "c_union: the width of `{f.name}` is not an integer"
                    return false
                }
                if (!add_member_bits(st, f, width_arg as tInt, size, storage, errors)) {
                    return false
                }
                continue
            }
            // a twin a source spells itself is the parser's error, before this runs
            for (by_ref in fixed_array(true, false)) {
                var fn <- make_operator(st, f, size, align, by_ref)
                compiling_module() |> add_function(fn)
            }
        }
        let at = st.fields[0].at
        while (length(st.fields) > 1) {
            st.fields |> erase(length(st.fields) - 1)
        }
        st.fields[0].name := "_storage"
        st.fields[0]._type = make_fixed_array_type(size / align, new TypeDecl(baseType = storage_of_bytes(align).base, at = at))
        return true
    }
}

c_runtime/c_volatile.das:
options gen2

module c_volatile public

require crt public
require daslib/ast
require daslib/ast_boost
require daslib/macro_boost
require daslib/templates_boost
require daslib/tune

//! C's volatile access: `c_volatile_load(x)` reads object `x` and `c_volatile_store(x, v)` writes
//! it, each once per call, so no tier folds a read or drops a write: the interpreter and the AOT
//! host through the `crt` forwarders, which access it through a `volatile` pointer, the JIT through
//! the `[llvm_code]` bodies of `c_volatile_jit.das`, one inlined `load volatile` or `store volatile`
//! each (c_runtime/ARCHITECTURE.md, the c_volatile.das entry). The object
//! comes by reference, so a converted module spells the access with no `addr`. One overload per C
//! scalar width, `bool` (C's `_Bool`) through its byte, and a pointer or function value through
//! its eight bytes.

def c_volatile_read(x : int8 const&) : int8 => unsafe(crt::c_volatile_load_i8(unsafe(addr(x))))
def c_volatile_read(x : uint8 const&) : uint8 => unsafe(crt::c_volatile_load_u8(unsafe(addr(x))))
def c_volatile_read(x : int16 const&) : int16 => unsafe(crt::c_volatile_load_i16(unsafe(addr(x))))
def c_volatile_read(x : uint16 const&) : uint16 => unsafe(crt::c_volatile_load_u16(unsafe(addr(x))))
def c_volatile_read(x : int const&) : int => unsafe(crt::c_volatile_load_i32(unsafe(addr(x))))
def c_volatile_read(x : uint const&) : uint => unsafe(crt::c_volatile_load_u32(unsafe(addr(x))))
def c_volatile_read(x : int64 const&) : int64 => unsafe(crt::c_volatile_load_i64(unsafe(addr(x))))
def c_volatile_read(x : uint64 const&) : uint64 => unsafe(crt::c_volatile_load_u64(unsafe(addr(x))))
def c_volatile_read(x : float const&) : float => unsafe(crt::c_volatile_load_f32(unsafe(addr(x))))
def c_volatile_read(x : double const&) : double => unsafe(crt::c_volatile_load_f64(unsafe(addr(x))))

def c_volatile_read(x : bool const&) : bool {
    unsafe {
        return crt::c_volatile_load_u8(addr<uint8 const?>(x)) != 0u8
    }
}

//! A pointer or a function value read once through its bits; the type rides through the reinterpret.
def c_volatile_read(x : auto(TT) const&) : TT -const -& {
    static_assert(typeinfo sizeof(type<TT>) == 8, "c_volatile_read: a scalar, a pointer or a function value")
    unsafe {
        return reinterpret<TT -const -&>(crt::c_volatile_load_u64(addr<uint64 const?>(x)))
    }
}

// the forwarder of each scalar type a load reaches directly
let private LOAD_FORWARDERS <- {
    Type.tInt8 => "c_volatile_load_i8", Type.tUInt8 => "c_volatile_load_u8",
    Type.tInt16 => "c_volatile_load_i16", Type.tUInt16 => "c_volatile_load_u16",
    Type.tInt => "c_volatile_load_i32", Type.tUInt => "c_volatile_load_u32",
    Type.tInt64 => "c_volatile_load_i64", Type.tUInt64 => "c_volatile_load_u64",
    Type.tFloat => "c_volatile_load_f32", Type.tDouble => "c_volatile_load_f64"
}

//! `c_volatile_load(x)`: one read of object `x`. A number expands in place to its `crt` forwarder
//! over `addr(x)`, so the interpreter makes one extern call where a function around it would add a
//! das call; `bool`, a pointer, a function value and a by-value parameter go through
//! `c_volatile_read`. Under the JIT every load goes through `c_volatile_load_jit`.
[call_macro(name = "c_volatile_load")]
class CVolatileLoadMacro : AstCallMacro {
    def override visit(prog : ProgramPtr; mod : Module?; var expr : ExprCallMacro?) : ExpressionPtr {
        macro_verify(length(expr.arguments) == 1, prog, expr.at, "c_volatile_load takes one object")
        var arg = expr.arguments[0]
        if (arg._type == null) {
            return <- default<ExpressionPtr>
        }
        var object = arg
        if (object is ExprRef2Value) {
            object = (object as ExprRef2Value).subexpr
        }
        let forwarder = LOAD_FORWARDERS?[arg._type.baseType] ?? ""
        // a by-value parameter is a reference the optimizer may replace with a caller's constant,
        // which has no address: its read goes through the fallback, whose `const&` binds anything
        let parameter = object is ExprVar && (object as ExprVar).varFlags.argument
        if (prog.policies.jit_enabled) {
            var generated <- qmacro(c_volatile::c_volatile_load_jit($e(arg)))
            generated.at = expr.at
            return <- generated
        }
        if (empty(forwarder) || !object._type.isRef || parameter) {
            // the module's own `c_volatile_read` by its qualified name, so a program's function of
            // that name cannot take the read; the error of a wrong argument names the call site
            var fallback <- qmacro(c_volatile::c_volatile_read($e(arg)))
            fallback.at = expr.at
            return <- fallback
        }
        // the object's address and the forwarder are the expansion's own, safe as the read is
        var ptr = new ExprRef2Ptr(at = expr.at, subexpr = clone_expression(object))
        ptr.genFlags.alwaysSafe = true
        var call = new ExprCall(at = expr.at, name := "crt::{forwarder}")
        call.genFlags.alwaysSafe = true
        call.arguments |> emplace(ptr)
        return <- call
    }
}

//! The JIT's load: a generic, so each instance lands in the das module of its caller and the
//! JIT's per-module partitions (`--jit-split-modules`, the cached DLL's default) still inline the
//! one `load volatile` its `[llvm_code]` generator emits; the body is the read on every other path.
[llvm_code(name = "c_volatile::load", version = 1)]
def c_volatile_load_jit(x : auto(TT) const&) : TT -const -& => c_volatile_read(x)

//! `bool` written as its byte: the JIT rejects a reinterpret of a `bool` to `uint8` (an `i1` to
//! `i8` bitcast), so it stays outside the generic.
def c_volatile_store(var x : bool&; v : bool) {
    unsafe {
        crt::c_volatile_store_u8(addr<uint8?>(x), v ? 1u8 : 0u8)
    }
}

//! `c_volatile_store(x, v)`: one write of object `x`, its bits through the unsigned forwarder of
//! its size (a pointer or a function value as its eight bytes). A generic for
//! the reason `c_volatile_load_jit` is one: under the JIT its `[llvm_code]` generator emits one
//! `store volatile` in the caller's module.
[llvm_code(name = "c_volatile::store", version = 1)]
def c_volatile_store(var x : auto(TT)&; v : TT) {
    static_assert(typeinfo sizeof(type<TT>) == 1 || typeinfo sizeof(type<TT>) == 2 || typeinfo sizeof(type<TT>) == 4 || typeinfo sizeof(type<TT>) == 8,
        "c_volatile_store: a scalar, a pointer or a function value")
    unsafe {
        static_if (typeinfo sizeof(type<TT>) == 1) {
            crt::c_volatile_store_u8(addr<uint8?>(x), reinterpret<uint8>(v))
        } static_elif (typeinfo sizeof(type<TT>) == 2) {
            crt::c_volatile_store_u16(addr<uint16?>(x), reinterpret<uint16>(v))
        } static_elif (typeinfo sizeof(type<TT>) == 4) {
            crt::c_volatile_store_u32(addr<uint?>(x), reinterpret<uint>(v))
        } else {
            crt::c_volatile_store_u64(addr<uint64?>(x), reinterpret<uint64>(v))
        }
    }
}

c_runtime/c_volatile_jit.das:
options gen2

module c_volatile_jit shared

require llvm/daslib/llvm_boost
require llvm/daslib/llvm_jit_code
require daslib/ast_boost

//! The JIT half of `c_volatile`: the `[llvm_code]` generators that emit the body of
//! `c_volatile_load_jit` and `c_volatile_store` as one LLVM `load volatile` or `store volatile`
//! through the object argument, which the JIT then inlines into its caller. The das bodies (the
//! `crt` forwarders) stay the interpreter's and the AOT host's, and the JIT's for `bool` and a
//! function value. Registered through the `llvm_code_generator` module group (`c_runtime/.das_module`).

// the C scalar widths the generators access as their own LLVM type, beside a pointer; `bool` and
// a function value keep the das body
let private ACCESSED_AS_IS = fixed_array(Type.tInt8, Type.tUInt8, Type.tInt16, Type.tUInt16, Type.tInt, Type.tUInt, Type.tInt64, Type.tUInt64, Type.tFloat, Type.tDouble)

def private accessed_as_is(t : TypeDeclPtr) : bool => t.isPointer || ACCESSED_AS_IS |> has_value(t.baseType)

// whether `t` is the object a generator accesses: a reference or a pointer
def private is_object(t : TypeDeclPtr) : bool => t.isPointer || t.isRef

// `(x : T const&) : T`: a volatile load of `T` through `x`
def private load_gen(var gc : LlvmCodeCtx) : bool {
    if (length(gc.fn.arguments) != 1 || !is_object(gc.fn.arguments[0]._type) || !accessed_as_is(gc.fn.result)) {
        return false
    }
    var entry = LLVMAppendBasicBlockInContext(gc.jit.ctx, gc.impl, "entry")
    LLVMPositionBuilderAtEnd(gc.jit.builder, entry)
    var value = LLVMBuildLoad2(gc.jit.builder, LLVMGetReturnType(gc.impl_type), LLVMGetParam(gc.impl, 0u), "c_volatile.load")
    LLVMSetVolatile(value, 1)
    LLVMSetAlignment(value, uint(gc.fn.result.alignOf))
    LLVMBuildRet(gc.jit.builder, value)
    return true
}

// `(var x : T&; v : T)`: a volatile store of `v` through `x`
def private store_gen(var gc : LlvmCodeCtx) : bool {
    if (length(gc.fn.arguments) != 2 || !is_object(gc.fn.arguments[0]._type) || !accessed_as_is(gc.fn.arguments[1]._type) || !gc.fn.result.isVoid) {
        return false
    }
    var entry = LLVMAppendBasicBlockInContext(gc.jit.ctx, gc.impl, "entry")
    LLVMPositionBuilderAtEnd(gc.jit.builder, entry)
    var store = LLVMBuildStore(gc.jit.builder, LLVMGetParam(gc.impl, 1u), LLVMGetParam(gc.impl, 0u))
    LLVMSetVolatile(store, 1)
    LLVMSetAlignment(store, uint(gc.fn.arguments[1]._type.alignOf))
    LLVMBuildRetVoid(gc.jit.builder)
    return true
}

//! The `llvm_code_generator` group member: dasLLVM's `llvm_user_modules` calls it before the
//! first generator lookup.
[macro_function]
def register_llvm_code_generators {
    register_llvm_code_generator("c_volatile::load", @@load_gen)
    register_llvm_code_generator("c_volatile::store", @@store_gen)
}

