module cstr public

require daslib/ast
require daslib/ast_boost
require daslib/macro_boost
require daslib/templates_boost

//! `cstr("abc")`: a C string literal as the `uint8?` of its bytes, NUL-terminated as C's. The call
//! expands in place to the one `reinterpret<uint8?>("abc")`, flagged safe, so converted code
//! carries no `unsafe` for it and the interpreter makes no call per literal. A call whose argument
//! is no string literal is left to a program's own `cstr`.
[call_macro(name = "cstr")]
class CstrMacro : AstCallMacro {
    def override visit(prog : ProgramPtr; mod : Module?; var expr : ExprCallMacro?) : ExpressionPtr {
        if (length(expr.arguments) != 1 || !(expr.arguments[0] is ExprConstString)) {
            var call = new ExprCall(at = expr.at, name := expr.name)
            for (arg in expr.arguments) {
                call.arguments |> emplace_new(clone_expression(arg))
            }
            return <- call
        }
        var expansion <- qmacro(reinterpret<uint8?>($e(expr.arguments[0])))
        expansion.at = expr.at
        expansion.genFlags.alwaysSafe = true
        return <- expansion
    }
}

c_runtime/cstr_array.das:
options gen2

module cstr_array public

require daslib/ast
require daslib/ast_boost
require daslib/macro_boost
require daslib/templates_boost

//! `cstr_array("abc", 16)`: the C `char buf[16] = "abc"` initializer as a `uint8[16]`
//! literal built at compile time - the bytes, a NUL, zero padding to the dimension. A string
//! that fills the array exactly gets no NUL, as in C; a longer one is a compile error.
[call_macro(name = "cstr_array")]
class CstrArrayMacro : AstCallMacro {
    def override visit(prog : ProgramPtr; mod : Module?; var expr : ExprCallMacro?) : ExpressionPtr {
        macro_verify(length(expr.arguments) == 2, prog, expr.at, "cstr_array takes a string literal and a dimension")
        macro_verify(expr.arguments[0] is ExprConstString, prog, expr.at, "cstr_array: the first argument is a string literal")
        macro_verify(expr.arguments[1] is ExprConstInt, prog, expr.at, "cstr_array: the second argument is an integer literal")
        let text = string((expr.arguments[0] as ExprConstString).value)
        let dim = (expr.arguments[1] as ExprConstInt).value
        macro_verify(length(text) <= dim, prog, expr.at, "cstr_array: `{text}` does not fit {dim} bytes")
        var items : array<ExpressionPtr>
        items |> reserve(dim)
        for (ch in text) {
            items |> push(new ExprConstUInt8(at = expr.at, value = uint8(ch)))
        }
        for (_pad in range(dim - length(text))) {
            items |> push(new ExprConstUInt8(at = expr.at, value = uint8(0)))
        }
        return qmacro(fixed_array($a(items)))
    }
}

c_runtime/enum_from_int.das:
options gen2

module enum_from_int public

require daslib/ast
require daslib/ast_boost
require daslib/macro_boost
require daslib/templates_boost

//! `enum_from_int(type<E>, i)`: the C implicit int-to-enum conversion. An out-of-range value
//! survives by value, compares by value and prints as `enum N`. The call expands in place to the
//! one `unsafe(reinterpret<E>(i))`, so converted code carries no `unsafe` and the interpreter
//! makes no call per conversion. A call without the witness is left to a program's own
//! `enum_from_int`.
[call_macro(name = "enum_from_int")]
class EnumFromIntMacro : AstCallMacro {
    def override visit(prog : ProgramPtr; mod : Module?; var expr : ExprCallMacro?) : ExpressionPtr {
        if (length(expr.arguments) != 2 || !(expr.arguments[0] is ExprTypeDecl)) {
            // no type witness: a call of a program's own `enum_from_int`, which overloading resolves
            var call = new ExprCall(at = expr.at, name := expr.name)
            for (arg in expr.arguments) {
                call.arguments |> emplace_new(clone_expression(arg))
            }
            return <- call
        }
        let witness = expr.arguments[0]._type
        let value = expr.arguments[1]._type
        if (witness == null || value == null) {
            return <- default<ExpressionPtr>
        }
        macro_verify(witness.isEnum, prog, expr.at, "enum_from_int: the witness is an enum type")
        macro_verify(value.baseType == Type.tInt, prog, expr.at, "enum_from_int: the value is an int")
        var expansion <- qmacro(reinterpret<$t(witness)>($e(expr.arguments[1])))
        expansion.at = expr.at
        expansion.genFlags.alwaysSafe = true
        return <- expansion
    }
}

