options gen2

module int_of public

require daslib/ast
require daslib/ast_boost
require daslib/macro_boost
require daslib/templates_boost

//! `int_of(a < b)`: C's int value of a truth, 1 or 0. The call expands in place to `a < b ? 1 : 0`
//! once its argument is inferred, so the interpreter makes no call for it and every tier runs the
//! node the spelled ternary is. A call whose argument is no `bool` is a compile error: das has no
//! `int(bool)`, and the name is the converter's, never a program's.
[call_macro(name = "int_of")]
class IntOfMacro : AstCallMacro {
    def override visit(prog : ProgramPtr; mod : Module?; var expr : ExprCallMacro?) : ExpressionPtr {
        if (length(expr.arguments) != 1) {
            macro_error(prog, expr.at, "int_of takes one bool")
            return <- default<ExpressionPtr>
        }
        if (expr.arguments[0]._type == null) {
            return <- default<ExpressionPtr>
        }
        if (!expr.arguments[0]._type.isBool) {
            macro_error(prog, expr.at, "int_of takes a bool, not {describe(expr.arguments[0]._type)}")
            return <- default<ExpressionPtr>
        }
        var expansion <- qmacro($e(expr.arguments[0]) ? 1 : 0)
        expansion.at = expr.at
        return <- expansion
    }
}

c_runtime/printf.das:
options gen2

module printf public

require strings
require math
require daslib/strings_boost
require crt
require c_runtime/variadic public

//! The printf family over a `CVaList`: the C format is split at its directives and every
//! directive is rendered by the CRT's own `snprintf` with one argument of its C type, so the
//! bytes are the CRT's byte for byte and no conversion engine lives in das. `c_vformat` is the
//! splitter, `c_vsnprintf`, `c_vsprintf` and `c_vprintf` its `CVaList` fronts (a forwarded
//! `va_list` arrives as `va_rest` of its cursor), `c_vfprintf` the front onto a CRT stream, and
//! `printf`, `fprintf`, `sprintf` and `snprintf` are `[variadic]` over them.

//! The width in bits of the dialect's `long`, which a `l` length modifier names: 64 under
//! `linux`, 32 under `msvc`. A converted module sets it before `main` (`c2das_dialect`); the
//! default is the host CRT's own.
var c_long_bits = crt::LONG_BITS

//! The C `EOF`, which the scanf family returns when the input ends before the first conversion.
let C_EOF = -1

//! One `%` directive of a C format, shared by the printf and the scanf families: its text with
//! `*` kept, its conversion, its length modifier, whether a `*` leads it (a width for printf, a
//! suppressed assignment for scanf), whether one stands for the precision, and the index just
//! past it. A scanf set (`%[^,]`) runs to its closing `]`.
struct CFormatDirective {
    spec : string
    conv : int
    length_mod : string
    leading_star : bool
    star_precision : bool
    end : int
}

def private is_flag(b : int) : bool => b == '-' || b == '+' || b == ' ' || b == '#' || b == '0'

def private is_length(b : int) : bool => b == 'h' || b == 'l' || b == 'j' || b == 'z' || b == 't' || b == 'L'

//! The directive starting at fmt[at] == '%'; under `scanf` a `*` is followed by the width, where
//! a printf `*` takes the width's place.
def c_parse_directive(fmt : uint8?; at : int; scanf : bool = false) : CFormatDirective {
    var d : CFormatDirective
    var idx = at + 1
    unsafe {
        while (is_flag(int(deref(fmt + idx)))) {
            idx++
        }
        if (int(deref(fmt + idx)) == '*') {
            d.leading_star = true
            idx++
        }
        if (scanf || !d.leading_star) {
            while (crt::isdigit(int(deref(fmt + idx))) != 0) {
                idx++
            }
        }
        if (int(deref(fmt + idx)) == '.') {
            idx++
            if (int(deref(fmt + idx)) == '*') {
                d.star_precision = true
                idx++
            } else {
                while (crt::isdigit(int(deref(fmt + idx))) != 0) {
                    idx++
                }
            }
        }
        let mod_start = idx
        while (is_length(int(deref(fmt + idx)))) {
            idx++
        }
        d.length_mod = unsafe(reinterpret<string>(fmt + mod_start)) |> slice(0, idx - mod_start)
        d.conv = int(deref(fmt + idx))
        if (d.conv == '[') {
            // the set runs to the first `]` past a leading `^` and a leading `]`
            idx++
            if (int(deref(fmt + idx)) == '^') {
                idx++
            }
            if (int(deref(fmt + idx)) == ']') {
                idx++
            }
            while (int(deref(fmt + idx)) != 0 && int(deref(fmt + idx)) != ']') {
                idx++
            }
        }
        if (int(deref(fmt + idx)) == 0) {
            // a format ending inside the directive: the directive stops at the NUL
            idx--
        }
        d.end = idx + 1
        d.spec = unsafe(reinterpret<string>(fmt + at)) |> slice(0, d.end - at)
    }
    return d
}

//! Whether a directive converts an integer (`%n` included, which stores one).
def c_is_int_conversion(d : CFormatDirective) : bool {
    let c = d.conv
    return c == 'd' || c == 'i' || c == 'u' || c == 'o' || c == 'x' || c == 'X' || c == 'n'
}

def private is_signed_conv(d : CFormatDirective) : bool => d.conv == 'd' || d.conv == 'i' || d.conv == 'c'

//! Whether a length modifier names a 64-bit integer: `l` where the dialect's `long` is one,
//! and `L`, which glibc takes as `ll` on an integer conversion.
def c_is_wide_length(mod : string) : bool =>
    mod == "ll" || mod == "L" || mod == "j" || mod == "z" || mod == "t" || (mod == "l" && c_long_bits == 64)

//! Whether a directive converts a floating value.
def c_is_float_conversion(d : CFormatDirective) : bool {
    let c = d.conv
    return c == 'f' || c == 'F' || c == 'e' || c == 'E' || c == 'g' || c == 'G' || c == 'a' || c == 'A'
}

//! A directive's text `spec` as the host CRT must read it, so its `long` never matters: an
//! integer `l` is the dialect's width (none for 32 bits, `ll` for 64), an integer `L` is `ll`,
//! a floating `L` is `l` (the dialect's `long double` is a `double`). A wide `%lc`, `%ls` or
//! `%l[` panics where the dialect's `wchar_t` is not the host's, which is where its `long` is
//! not (msvc's 2-byte `wchar_t`, linux's 4).
def c_dialect_spec(d : CFormatDirective; spec : string) : string {
    let m = d.length_mod
    if (m != "l" && m != "L") {
        return spec
    }
    let conv_at = d.conv == '[' ? find(spec, "[") : length(spec) - 1
    let head = slice(spec, 0, conv_at - length(m))
    let tail = slice(spec, conv_at)
    if (d.conv == 'c' || d.conv == 's' || d.conv == '[') {
        if (m == "l" && c_long_bits != crt::LONG_BITS) {
            panic("`{spec}`: a wide character directive under a dialect whose wchar_t is not the host's is not supported")
        }
        return spec
    }
    if (c_is_float_conversion(d)) {
        return m == "L" ? "{head}l{tail}" : spec
    }
    if (c_is_int_conversion(d)) {
        return c_is_wide_length(m) ? "{head}ll{tail}" : "{head}{tail}"
    }
    return spec
}

// `spec` with each `*` replaced by the value it consumed, so the CRT sees a literal directive
def private resolve_stars(d : CFormatDirective; var v : CVaCursor) : string {
    if (!d.leading_star && !d.star_precision) {
        return d.spec
    }
    var width = 0l
    var precision = 0l
    if (d.leading_star) {
        width = va_i(v)
    }
    if (d.star_precision) {
        precision = va_i(v)
    }
    return build_string() $(var w) {
        var seen_dot = false
        for (ch in d.spec) {
            if (ch == '*') {
                w |> write(seen_dot ? "{precision}" : "{width}")
            } else {
                if (ch == '.') {
                    seen_dot = true
                }
                w |> write(to_char(ch))
            }
        }
    }
}

// one directive's argument popped and rendered into `buf` by the CRT call its conversion and
// length name; the rendered length, as `snprintf` reports it
def private render_into(d : CFormatDirective; var v : CVaCursor; buf : uint8?; cap : uint64; fmt : uint8?) : int {
    unsafe {
        if (d.conv == '%') {
            return crt::snprintf_none(buf, cap, fmt)
        } elif (c_is_int_conversion(d) || d.conv == 'c') {
            let n = va_i(v)
            if (c_is_wide_length(d.length_mod)) {
                return is_signed_conv(d) ? crt::snprintf_int64(buf, cap, fmt, n) : crt::snprintf_uint64(buf, cap, fmt, uint64(n))
            }
            return is_signed_conv(d) ? crt::snprintf_int(buf, cap, fmt, int(n)) : crt::snprintf_uint(buf, cap, fmt, uint(n))
        } elif (c_is_float_conversion(d)) {
            return crt::snprintf_double(buf, cap, fmt, va_d(v))
        } elif (d.conv == 's') {
            return crt::snprintf_str(buf, cap, fmt, reinterpret<uint8?>(va_p(v)))
        } elif (d.conv == 'p') {
            return crt::snprintf_ptr(buf, cap, fmt, va_p(v))
        }
    }
    panic("printf: conversion `{d.spec}` is not supported")
}

// one directive rendered into `out`, retried into a CRT buffer from the same argument when the
// 512-byte scratch is short
def private render(d : CFormatDirective; var v : CVaCursor; var out : array<uint8>) {
    if (d.conv == 'n') {
        panic("printf: `%n` is not supported")
    }
    let spec = c_dialect_spec(d, resolve_stars(d, v))
    let fmt = unsafe(reinterpret<uint8?>(spec))
    let at = v.at
    var tmp : uint8[512]
    let cap = uint64(typeinfo dim(tmp))
    var n = render_into(d, v, unsafe(addr(tmp[0])), cap, fmt)
    if (n < 0) {
        panic("printf: the CRT rejected `{spec}`")
    }
    out |> reserve(length(out) + n)
    if (uint64(n) < cap) {
        for (idx in range(n)) {
            out |> push(tmp[idx])
        }
        return
    }
    unsafe {
        var big = reinterpret<uint8?>(crt::malloc(uint64(n) + 1ul))
        v.at = at
        n = render_into(d, v, big, uint64(n) + 1ul, fmt)
        for (idx in range(n)) {
            out |> push(deref(big + idx))
        }
        crt::free(big)
    }
}

//! The rendered bytes of `fmt` over `va`, no NUL: the splitter every front shares.
def c_vformat(fmt : uint8?; va : CVaList) : array<uint8> {
    var out : array<uint8>
    if (fmt == null) {
        return <- out
    }
    var v = va_begin(va)
    var idx = 0
    while (true) {
        let at = unsafe(fmt + idx)
        let b = deref(at)
        if (b == uint8(0)) {
            break
        }
        if (int(b) != '%') {
            out |> push(b)
            idx++
            continue
        }
        let d = c_parse_directive(fmt, idx)
        render(d, v, out)
        idx = d.end
    }
    return <- out
}

//! C `vsnprintf`: at most `size - 1` bytes plus a NUL into `buf` (nothing when `size` is 0),
//! the full rendered length returned.
def c_vsnprintf(var buf : uint8?; size : uint64; fmt : uint8?; va : CVaList) : int {
    let bytes <- c_vformat(fmt, va)
    let total = length(bytes)
    if (size > 0ul) {
        let room = int(min(uint64(total), size - 1ul))
        unsafe {
            for (idx in range(room)) {
                deref(buf + idx) = bytes[idx]
            }
            deref(buf + room) = uint8(0)
        }
    }
    return total
}

//! C `vsprintf`: `c_vsnprintf` with no bound, the caller's buffer taken to be large enough.
def c_vsprintf(var buf : uint8?; fmt : uint8?; va : CVaList) : int => c_vsnprintf(buf, 0xFFFFFFFFul, fmt, va)

//! C `vprintf`: the bytes go to the CRT's stdout, so they interleave with every bound CRT
//! write in order and `exit_now` flushes them.
def c_vprintf(fmt : uint8?; va : CVaList) : int {
    let bytes <- c_vformat(fmt, va)
    if (!empty(bytes)) {
        unsafe {
            crt::fwrite_stdout(addr(bytes[0]), uint64(long_length(bytes)))
        }
    }
    return length(bytes)
}

//! C `vfprintf`: the bytes go through the CRT's `fwrite` to `f`, a `FILE *` as `void?`, so they
//! interleave with every other bound write to the stream in order.
def c_vfprintf(var f : void?; fmt : uint8?; va : CVaList) : int {
    let bytes <- c_vformat(fmt, va)
    if (!empty(bytes)) {
        unsafe {
            crt::fwrite(addr(bytes[0]), 1ul, uint64(long_length(bytes)), f)
        }
    }
    return length(bytes)
}

[variadic]
def printf(fmt : uint8?; va : va_args) : int {
    return c_vprintf(fmt, va)
}

[variadic]
def sprintf(var buf : uint8?; fmt : uint8?; va : va_args) : int {
    return c_vsprintf(buf, fmt, va)
}

[variadic]
def snprintf(var buf : uint8?; size : uint64; fmt : uint8?; va : va_args) : int {
    return c_vsnprintf(buf, size, fmt, va)
}

[variadic]
def fprintf(var f : void?; fmt : uint8?; va : va_args) : int {
    return c_vfprintf(f, fmt, va)
}

c_runtime/scanf.das:
options gen2

module scanf public

require crt
require strings
require c_runtime/variadic public
require c_runtime/printf public

//! The scanf family over a `CVaList`, the printf family's split run backwards: the C format is
//! read directive by directive (`c_parse_directive`, shared with printf), and every conversion
//! is the CRT's own `sscanf` over that one directive and a trailing `%n`, writing through the
//! C program's out-pointer at the width the directive names and reporting the bytes it took,
//! so the input moves on by exactly what the CRT consumed. Whitespace and ordinary characters
//! of the format match in das, as C defines them. `c_vsscanf` is the splitter, `sscanf` the
//! `[variadic]` front; `c_vfscanf` and `fscanf` the same over a stream, each piece the CRT's
//! `fscanf`.

// `%n`: the bytes consumed so far, stored at the width its length modifier names
def private store_percent_n(d : CFormatDirective; var out : void?; consumed : int) {
    unsafe {
        let m = d.length_mod
        if (m == "hh") {
            deref(reinterpret<int8?>(out)) = int8(consumed)
        } elif (m == "h") {
            deref(reinterpret<int16?>(out)) = int16(consumed)
        } elif (c_is_wide_length(m)) {
            deref(reinterpret<int64?>(out)) = int64(consumed)
        } else {
            deref(reinterpret<int?>(out)) = consumed
        }
    }
}

def private crt_piece(d : CFormatDirective) : string => "{c_dialect_spec(d, d.spec)}%n"

// the conversions C's scanf defines; a glibc extension (`%m`, `%q`, `%1$d`) is not one
def private is_scanf_conversion(d : CFormatDirective) : bool =>
    c_is_int_conversion(d) || c_is_float_conversion(d) || d.conv == 's' || d.conv == 'c' || d.conv == '[' || d.conv == 'p' || d.conv == '%'

//! C `vsscanf`: the count of assignments made, or `C_EOF` when the input ends before the
//! first conversion; a directive that does not match stops the scan. A null format reads
//! nothing.
def c_vsscanf(src : uint8?; fmt : uint8?; va : CVaList) : int {
    if (fmt == null) {
        return 0
    }
    if (src == null) {
        panic("sscanf: the input is a null pointer")
    }
    var v = va_begin(va)
    var count = 0
    var pos = 0
    var idx = 0
    unsafe {
        while (true) {
            let b = int(deref(fmt + idx))
            if (b == 0) {
                break
            }
            if (crt::isspace(b) != 0) {
                // a whitespace directive takes any run of input whitespace, none included
                while (crt::isspace(int(deref(fmt + idx))) != 0) {
                    idx++
                }
                while (crt::isspace(int(deref(src + pos))) != 0) {
                    pos++
                }
                continue
            }
            if (b != '%') {
                let c = int(deref(src + pos))
                if (c == 0) {
                    return count == 0 ? C_EOF : count
                }
                if (c != b) {
                    return count
                }
                pos++
                idx++
                continue
            }
            let d = c_parse_directive(fmt, idx, true)
            idx = d.end
            if (!is_scanf_conversion(d)) {
                panic("sscanf: directive `{d.spec}` is not supported")
            }
            if (d.conv == 'n') {
                if (!d.leading_star) {
                    store_percent_n(d, va_p(v), pos)
                }
                continue
            }
            let assigns = !d.leading_star && d.conv != '%'
            let piece = crt_piece(d)
            var consumed = -1
            let r = assigns ? crt::sscanf_one(src + pos, reinterpret<uint8?>(piece), va_p(v), addr(consumed)) : crt::sscanf_none(src + pos, reinterpret<uint8?>(piece), addr(consumed))
            if (r < 0) {
                return count == 0 ? C_EOF : count
            }
            if (consumed < 0) {
                return count
            }
            pos += consumed
            if (assigns) {
                count++
            }
        }
    }
    return count
}

[variadic]
def sscanf(src : uint8?; fmt : uint8?; va : va_args) : int {
    return c_vsscanf(src, fmt, va)
}

// one piece of a format over stream `f`: the CRT's `fscanf` of `piece` (ending in `%n`), through
// `out` when it assigns; the CRT's result, `consumed` the bytes it took or -1 when it stopped short
def private fscanf_piece(var f : void?; piece : string; assigns : bool; var out : void?; var consumed : int&) : int {
    consumed = -1
    unsafe {
        return assigns ? crt::fscanf_one(f, reinterpret<uint8?>(piece), out, addr(consumed)) : crt::fscanf_none(f, reinterpret<uint8?>(piece), addr(consumed))
    }
}

// the result of a piece that matched nothing, below every byte count and apart from `C_EOF`
let private FSCANF_MISMATCH = -2

// a piece of the format that assigns nothing over `f` (a whitespace run `" %n"`, an ordinary
// character `"x%n"`): the bytes it consumed, `FSCANF_MISMATCH` when the character did not match,
// `C_EOF` when the input ended first
def private fscanf_literal(var f : void?; piece : string) : int {
    var consumed = -1
    var none : void?
    if (fscanf_piece(f, piece, false, none, consumed) < 0) {
        return C_EOF
    }
    return consumed < 0 ? FSCANF_MISMATCH : consumed
}

//! C `vfscanf` over a `FILE *` as `void?`: `c_vsscanf`'s split, each piece the CRT's `fscanf`
//! over the stream: a whitespace run, an ordinary character, or one directive, each with a
//! trailing `%n`, so the stream moves by exactly what the CRT consumed. The count of assignments,
//! or `C_EOF` when the input ends before the first conversion.
def c_vfscanf(var f : void?; fmt : uint8?; va : CVaList) : int {
    if (fmt == null) {
        return 0
    }
    var v = va_begin(va)
    var count = 0
    var pos = 0
    var idx = 0
    unsafe {
        while (true) {
            let b = int(deref(fmt + idx))
            if (b == 0) {
                break
            }
            if (b != '%') {
                let ws = crt::isspace(b) != 0
                while (ws && crt::isspace(int(deref(fmt + idx))) != 0) {
                    idx++
                }
                let took = fscanf_literal(f, ws ? " %n" : "{to_char(b)}%n")
                if (took == C_EOF) {
                    return count == 0 ? C_EOF : count
                }
                if (took == FSCANF_MISMATCH) {
                    return count
                }
                pos += took
                idx += ws ? 0 : 1
                continue
            }
            let d = c_parse_directive(fmt, idx, true)
            idx = d.end
            if (!is_scanf_conversion(d)) {
                panic("fscanf: directive `{d.spec}` is not supported")
            }
            if (d.conv == 'n') {
                if (!d.leading_star) {
                    store_percent_n(d, va_p(v), pos)
                }
                continue
            }
            let assigns = !d.leading_star && d.conv != '%'
            var none : void?
            var out = assigns ? va_p(v) : none
            var consumed = -1
            let r = fscanf_piece(f, crt_piece(d), assigns, out, consumed)
            if (r < 0) {
                return count == 0 ? C_EOF : count
            }
            if (consumed < 0) {
                return count
            }
            pos += consumed
            count += assigns ? 1 : 0
        }
    }
    return count
}

[variadic]
def fscanf(var f : void?; fmt : uint8?; va : va_args) : int {
    return c_vfscanf(f, fmt, va)
}

c_runtime/setjmp.das:
options gen2

module setjmp public

require daslib/rtti

//! The setjmp/longjmp protocol over das's own unwinding (docs/lowering-examples.md "setjmp /
//! longjmp"): `c_longjmp` records the target buffer and its value and panics; the `recover` of
//! every setjmp site the unwind passes compares `c_jmp_target` with its own buffer, rethrows
//! another's, and clears it for its own. das skips `finally` on a panic, which is C's
//! no-cleanup-on-longjmp rule. A genuine das panic leaves the target null, so every site
//! rethrows it.

struct CJmpBuf {
    val : int
}

//! The buffer a longjmp in flight targets; null when no longjmp is in flight.
var c_jmp_target : CJmpBuf?

//! C `longjmp(buf, v)`: never returns; a zero value arrives as 1, as C says. Every converted
//! pointer parameter is `var` (F3), so the buffer arrives writable.
def c_longjmp(var buf : CJmpBuf?; v : int) {
    buf.val = v == 0 ? 1 : v
    c_jmp_target = buf
    panic("longjmp")
}

//! The `recover` of a setjmp site a panic passes that is not a longjmp to its own buffer: a
//! longjmp to another buffer goes on as one; any other panic (none in flight) goes on with its own
//! message, which a bare rethrow of "longjmp" would hide.
def c_jmp_rethrow {
    if (c_jmp_target != null) {
        panic("longjmp")
    }
    panic(this_context().last_exception)
}

c_runtime/variadic.das:
options gen2

module variadic public

require daslib/ast
require daslib/ast_boost
require daslib/apply
require daslib/macro_boost
require daslib/templates_boost

//! C varargs as a generic over a trailing tuple. `[variadic] def f(fixed...; va : va_args)`
//! becomes `f`va(fixed...; _va_tuple : auto)` whose body opens with `let va <- to_cvalist(_va_tuple)`,
//! and a call macro named `f` tuples every argument past the fixed ones, so a converted call
//! site `f(a, 1, 2.5)` stays spelled as C spells it. A C `va_list` is a `CVaCursor` over that
//! list, and `va_arg(v, T)` is a typed pop at it; a mismatch panics, which is the C undefined
//! behavior made visible.

variant CVal {
    i : int64
    d : double
    p : void?
}

typedef CVaList = array<CVal>

//! The declared type of the trailing parameter; the annotation replaces it.
struct va_args {}

//! The call shape with no trailing argument at all.
struct VaNone {}

[unused_argument(va)]
def to_cvalist(va : VaNone) : CVaList {
    var lst : CVaList
    return <- lst
}

//! A list already built, which a late-bound variadic call forwards from its wrapper
//! (`converter/ARCHITECTURE_LAYOUT.md`): the list as it is, copied.
def to_cvalist(va : CVaList) : CVaList => <- clone_to_move(va)

//! The prologue converter: one `CVal` per tuple field, C's default argument promotions applied -
//! `float` widens to `double`, every integer class including `bool` and enums widens to `int64`,
//! any pointer or function value travels as `void?`.
def to_cvalist(va : auto) : CVaList {
    var lst : CVaList
    apply(va) $(name, field) {
        static_if (typeinfo is_pointer(field) || typeinfo is_function(field)) {
            lst |> push(CVal(p = unsafe(reinterpret<void?>(field))))
        } static_elif (typeinfo is_float(field)) {
            lst |> push(CVal(d = double(field)))
        } static_elif (typeinfo is_double(field)) {
            lst |> push(CVal(d = field))
        } static_elif (typeinfo stripped_typename(field) == "bool") {
            lst |> push(CVal(i = field ? 1l : 0l))
        } else {
            lst |> push(CVal(i = int64(field)))
        }
    }
    return <- lst
}

//! A C `va_list` object: the address of the function's list and the position of the next
//! argument. Assignment copies both, which is `va_copy`; a `var` parameter of this type is the
//! caller's own cursor, which is the linux `va_list` parameter (an array decayed to a pointer).
struct CVaCursor {
    list : CVaList const?
    at : int
}

//! `va_start`: a cursor at the first trailing argument of `va`, the list the prologue bound.
def va_begin(va : CVaList) : CVaCursor => CVaCursor(list = unsafe(addr(va)), at = 0)

// the arms of `CVal` by variant index, as the pops name them
let private ARM_NAMES = fixed_array("an integer", "a double", "a pointer")

let private ARM_I = 0

let private ARM_D = 1

let private ARM_P = 2

def private va_take(var v : CVaCursor; arm : int) : CVal {
    if (v.list == null) {
        panic("va_arg reads {ARM_NAMES[arm]} from a va_list no va_start began")
    }
    let count = length(deref(v.list))
    if (v.at >= count) {
        panic("va_arg reads {ARM_NAMES[arm]} at trailing argument {v.at}, past the {count} passed")
    }
    let c = deref(v.list)[v.at]
    let found = variant_index(c)
    let zero_pointer = arm == ARM_P && c is i && c as i == 0l
    if (found != arm && !(arm == ARM_I && found == ARM_P) && !zero_pointer) {
        panic("va_arg reads {ARM_NAMES[arm]} where trailing argument {v.at} is {ARM_NAMES[found]}")
    }
    v.at++
    return c
}

//! `va_arg` of an integer type: the `int64` the argument was promoted to, or a pointer's bits.
def va_i(var v : CVaCursor) : int64 {
    let c = va_take(v, ARM_I)
    return c is p ? int64(intptr(c as p)) : c as i
}

//! `va_arg` of `double` (and of `float`, which no argument arrives as).
def va_d(var v : CVaCursor) : double => va_take(v, ARM_D) as d

//! `va_arg` of a pointer type, a function pointer included; an integer zero reads as null.
def va_p(var v : CVaCursor) : void? {
    let c = va_take(v, ARM_P)
    return c is i ? null : c as p
}

//! The arguments from the cursor on, as the list a `CVaList` callee takes (`c_vprintf`): the
//! forwarding of a `va_list`.
def va_rest(v : CVaCursor) : CVaList {
    if (v.list == null) {
        var none : CVaList
        return <- none
    }
    return <- subarray(deref(v.list), range(v.at, length(deref(v.list))))
}

class VariadicCallMacro : AstCallMacro {
    target : string
    fixed : int
    def override visit(prog : ProgramPtr; mod : Module?; var expr : ExprCallMacro?) : ExpressionPtr {
        let n = length(expr.arguments)
        macro_verify(n >= fixed, prog, expr.at, "{expr.name} takes at least {fixed} argument(s)")
        var fixed_args : array<ExpressionPtr>
        fixed_args |> reserve(fixed)
        for (idx in range(fixed)) {
            fixed_args |> push(clone_expression(expr.arguments[idx]))
        }
        var tail : ExpressionPtr
        if (n == fixed) {
            tail = qmacro(VaNone())
        } else {
            var tup = new ExprMakeTuple(at = expr.at)
            for (idx in range(fixed, n)) {
                tup.values |> push(clone_expression(expr.arguments[idx]))
            }
            tail = tup
        }
        return qmacro($c(target)($a(fixed_args), $e(tail)))
    }
}

def private is_va_args(t : TypeDeclPtr) : bool =>
    t != null && t.baseType == Type.tStructure && t.structType != null && t.structType.name == "va_args"

[function_macro(name = "variadic")]
class VariadicAnnotation : AstFunctionAnnotation {
    def override apply(var func : FunctionPtr; var group : ModuleGroup; var args : AnnotationArgumentList; var errors : das_string) : bool {
        let n = length(func.arguments)
        if (n == 0 || !is_va_args(func.arguments[n - 1]._type)) {
            errors := "[variadic] needs a trailing parameter of type va_args"
            return false
        }
        var last = func.arguments[n - 1]
        let list_name = string(last.name)
        last.name := "_va_tuple"
        last._type = new TypeDecl(baseType = Type.autoinfer, at = last.at)
        var wrapped = qmacro_block() {
            let $i(list_name) <- to_cvalist(_va_tuple)
            $e(func.body)
        }
        var prologue = unsafe(reinterpret<ExprBlock?>(wrapped))
        prologue.at = func.at
        for (idx in range(length(prologue.list))) {
            prologue.list[idx].at = func.at
        }
        func.body = prologue
        let c_name = string(func.name)
        let target = "{c_name}`va"
        func.name := target
        var macro = new VariadicCallMacro(target = target, fixed = n - 1)
        compiling_module() |> add_call_macro(make_call_macro(c_name, macro))
        return true
    }
}
